const DEFAULT_NATIVE_METER_PORT: u16 = 2222;
const DEFAULT_OSC_PORT: u16 = 2223;

// Maillot OSC uses UDP 2223 in production. Unit tests redirect only their
// loopback fake desk to a private port; a local emulator must not skip coverage.
fn console_osc_target(wing_ip: impl std::fmt::Display) -> String {
    let port = DEFAULT_OSC_PORT;
    #[cfg(test)]
    let port = if wing_ip.to_string() == "127.0.0.1" { fake_console_port() } else { port };
    format!("{wing_ip}:{port}")
}

#[cfg(test)]
fn fake_console_port() -> u16 {
    static PORT: OnceLock<u16> = OnceLock::new();
    *PORT.get_or_init(|| std::net::UdpSocket::bind("127.0.0.1:0")
        .expect("reserve a private test port").local_addr().expect("test socket address").port())
}

const DEFAULT_DISCOVERY_PORT: u16 = 2222;
const DEFAULT_REPORT_ID: u32 = 1;
const RENEW_INTERVAL: Duration = Duration::from_secs(2);
const UDP_RECEIVE_TIMEOUT: Duration = Duration::from_millis(250);
const CONNECT_TIMEOUT: Duration = Duration::from_millis(3000);
const OSC_SEND_INTERVAL: Duration = Duration::from_millis(17);
const OSC_MAX_QUEUE_DELAY: Duration = Duration::from_secs(1);
// A leaf read is the only authoritative way to observe OSC state: the console
// reports changes only and never re-publishes state on a /*S subscribe or renew
// (measured on WING Rack, FW 3.1.1). One address is refreshed per step,
// and only when a send slot is already free, so a missed UDP event self-heals
// without ever delaying the meter receive loop.
const OSC_STATE_REFRESH_STEP: Duration = Duration::from_millis(500);
// A leaf read is the only way to observe OSC state from the app, and it is a request/answer round trip,
// so it is bounded. It serves the readers that legitimately need an answer — the strip and FX model the
// editor reads, and the read-back that reports whether a `set` or a ramp landed. It is **not** the toggle
// path: a toggle sends the console's own `-1` and reads nothing at all (Maillot 3.1.0, "Special case:
// Toggle", scratch/wing_protocols.txt:782-789). Measured at about 1 ms on a wired LAN; anything close to
// this bound means the console is not answering and the caller fails closed rather than guessing.
const LEAF_READ_TIMEOUT: Duration = Duration::from_millis(400);
// The read-back that reports whether a write landed has its own, much smaller, bounds, because it is
// a diagnostic and not a decision: the settle budget is the whole cost one step's verification may
// add to a macro run, and one attempt inside it is the send-limiter wait plus this read timeout. The
// console answers a leaf read in about a millisecond on a wired LAN, and an address that does not
// exist never answers at all, so a shorter attempt loses nothing and bounds the report.
const VERIFY_SETTLE_BUDGET: Duration = Duration::from_millis(250);
const VERIFY_READ_TIMEOUT: Duration = Duration::from_millis(60);
const IDENTITY_PROBE_TIMEOUT: Duration = Duration::from_millis(650);

struct WingRoute {
    hub: UdpHub,
    local_ip: Option<Ipv4Addr>,
    interface_name: Option<String>,
    reply: Vec<u8>,
    source: SocketAddr,
}

fn ordered_local_interfaces(preferred: Option<&str>, strict: bool) -> Result<Vec<wing_transport::LocalIpv4Interface>, String> {
    let preferred = preferred.map(str::trim).filter(|name| !name.is_empty());
    let mut interfaces = local_ipv4_interfaces();
    if let Some(name) = preferred {
        if strict {
            interfaces.retain(|interface| interface.name == name);
            if interfaces.is_empty() {
                return Err(format!("Network adapter {name} is unavailable. Select another adapter in Settings or use Auto."));
            }
        } else {
            interfaces.sort_by_key(|interface| interface.name != name);
        }
    }
    Ok(interfaces)
}

fn receive_wing_identity(
    hub: &UdpHub,
    expected_ip: Option<Ipv4Addr>,
    timeout: Duration,
) -> Option<(Vec<u8>, SocketAddr)> {
    let deadline = Instant::now() + timeout;
    let mut buffer = [0_u8; 4096];
    while Instant::now() < deadline {
        let wait = deadline.saturating_duration_since(Instant::now());
        match hub.recv_once(&mut buffer, wait) {
            Ok((len, source)) if expected_ip.is_none_or(|ip| source.ip() == IpAddr::V4(ip))
                && buffer[..len].starts_with(b"WING,") =>
            {
                return Some((buffer[..len].to_vec(), source));
            }
            Ok(_) => {}
            Err(error) if matches!(error.kind(), std::io::ErrorKind::TimedOut | std::io::ErrorKind::WouldBlock) => break,
            Err(_) => break,
        }
    }
    None
}

fn probe_wing_route(wing_ip: Ipv4Addr, preferred: Option<&str>, strict: bool) -> Result<WingRoute, String> {
    let target = SocketAddrV4::new(wing_ip, DEFAULT_DISCOVERY_PORT);
    let mut attempted = Vec::new();
    // Maillot 3.1.0, "Remote communications with WING": send WING? to UDP 2222
    // and accept WING,... only from that console. Binding each local IPv4 source
    // avoids macOS choosing Wi-Fi when Ethernet shares the same subnet.
    for interface in ordered_local_interfaces(preferred, strict)? {
        attempted.push(format!("{} ({})", interface.name, interface.address));
        let Ok(hub) = UdpHub::bind_ipv4(interface.address, 0) else { continue };
        if hub.send_to(b"WING?", target).is_err() { continue; }
        if let Some((reply, source)) = receive_wing_identity(&hub, Some(wing_ip), IDENTITY_PROBE_TIMEOUT) {
            return Ok(WingRoute { hub, local_ip: Some(interface.address), interface_name: Some(interface.name), reply, source });
        }
    }
    if strict && preferred.is_some_and(|name| !name.trim().is_empty()) {
        return Err(format!("No WING? reply from {wing_ip}:2222 through selected adapter {}. Strict adapter mode prevented fallback.", attempted.join(", ")));
    }
    let hub = UdpHub::bind(0).map_err(|error| format!("WING discovery UDP bind failed: {error}"))?;
    attempted.push("system default".to_string());
    hub.send_to(b"WING?", target).map_err(|error| format!("WING? send failed: {error}"))?;
    if let Some((reply, source)) = receive_wing_identity(&hub, Some(wing_ip), IDENTITY_PROBE_TIMEOUT) {
        return Ok(WingRoute { hub, local_ip: None, interface_name: None, reply, source });
    }
    Err(format!("No WING? reply from {wing_ip}:2222 via {}. Check WING IP, console network settings and cable.", attempted.join(", ")))
}

fn connect_native_meter(wing_ip: Ipv4Addr, local_ip: Option<Ipv4Addr>) -> Result<NativeMeterTcp, String> {
    let remote = SocketAddrV4::new(wing_ip, DEFAULT_NATIVE_METER_PORT);
    let result = match local_ip {
        Some(source) => NativeMeterTcp::connect_from(source, remote, CONNECT_TIMEOUT),
        None => NativeMeterTcp::connect(remote, CONNECT_TIMEOUT),
    };
    result.map_err(|error| format!("native meter TCP connect {remote} from {} failed: {error}",
        local_ip.map_or_else(|| "system default".to_string(), |ip| ip.to_string())))
}

static ACTIVE_STREAM_STOP: OnceLock<Mutex<Option<Arc<AtomicBool>>>> = OnceLock::new();
static ACTIVE_METER_CHANNEL: OnceLock<Mutex<ActiveMeterChannelState>> = OnceLock::new();
static OSC_NEXT_SEND: OnceLock<Mutex<Instant>> = OnceLock::new();

/// The last console model the app learned from a discovery reply, with the desk it belongs to.
///
/// The desk announces its model itself — `WING,<ip>,<name>,<mdl>,…` (Maillot 563-567) — and the
/// whole family shares the protocol, so this is the only honest source for the answers the document
/// ties to a model: the length of the local input meter group (footnote 17, 1641) and whether
/// `/cfg/mon/<n>/$lvl` takes a write (footnote 13, 1357-1359). The catalogue and the step validator
/// read it here rather than assuming the desk this project was developed against; a stale entry from
/// another address is not reused, because answering for the wrong console is the defect.
static KNOWN_DESK_MODEL: OnceLock<Mutex<Option<(Ipv4Addr, DeskModel)>>> = OnceLock::new();

fn known_desk_model_slot() -> &'static Mutex<Option<(Ipv4Addr, DeskModel)>> {
    KNOWN_DESK_MODEL.get_or_init(|| Mutex::new(None))
}

/// Remembers the model a discovery reply announced for one desk.
fn remember_desk_model(wing_ip: Ipv4Addr, model: DeskModel) {
    if let Ok(mut slot) = known_desk_model_slot().lock() {
        *slot = Some((wing_ip, model));
    }
}

/// The model of the desk the app last talked to. `None` when no console has announced itself yet, or
/// when the one that did is not the desk being asked about — the caller then fails closed rather than
/// answering for a console it has never spoken to.
fn know_desk_model(wing_ip: Option<Ipv4Addr>) -> Option<DeskModel> {
    let slot = known_desk_model_slot().lock().ok()?;
    let (known_ip, model) = (*slot)?;
    match wing_ip {
        Some(wing_ip) if known_ip != wing_ip => None,
        _ => Some(model),
    }
}

/// Where a send has to leave from to reach one desk, remembered so the app does not ask again.
///
/// Discovery is a round trip to the console — `WING?` on UDP 2222 and its `WING,…` answer (Maillot
/// 563-567) — and it was paid **per operator action**: every Shoot, every raw send and every model
/// read probed the desk before doing its work. That is invisible on a quiet LAN and ruinous on a desk
/// that is busy streaming meters, because each adapter that does not answer costs the whole
/// `IDENTITY_PROBE_TIMEOUT` before the next one is tried: **measured on 2026-09-27 at 1.302 s** with one
/// adapter plus the system-default fallback, and up to 1.95 s with two adapters. What a send needs to
/// know does not change between two clicks of the same show, so the answer is kept here and reused. A
/// fresh socket is still bound per action, so two commands can never steal each other's replies.
#[derive(Clone)]
struct KnownWingRoute {
    wing_ip: Ipv4Addr,
    /// The adapter choice the answer belongs to: a different choice is a different route.
    preferred: Option<String>,
    strict: bool,
    local_ip: Option<Ipv4Addr>,
    learned_at: Instant,
}

/// How long a remembered route is trusted: long enough to cover a show's worth of clicks, short
/// enough that a cable moved to another network is noticed by the next action after a break.
const ROUTE_MEMORY_TTL: Duration = Duration::from_secs(600);

static KNOWN_WING_ROUTE: OnceLock<Mutex<Option<KnownWingRoute>>> = OnceLock::new();

fn known_wing_route_slot() -> &'static Mutex<Option<KnownWingRoute>> {
    KNOWN_WING_ROUTE.get_or_init(|| Mutex::new(None))
}

/// Remembers the route a discovery exchange (or the live stream) found for one desk.
fn remember_wing_route(
    wing_ip: Ipv4Addr,
    preferred: Option<&str>,
    strict: bool,
    local_ip: Option<Ipv4Addr>,
) {
    let Ok(mut slot) = known_wing_route_slot().lock() else {
        return;
    };
    *slot = Some(KnownWingRoute {
        wing_ip,
        preferred: preferred.map(str::to_string),
        strict,
        local_ip,
        learned_at: Instant::now(),
    });
}

/// Forgets the remembered route: the next action asks the desk again. Called when a send or a read
/// fails, because the cable may have moved and the remembered source address is then the suspect.
fn forget_wing_route() {
    if let Ok(mut slot) = known_wing_route_slot().lock() {
        *slot = None;
    }
}

/// The remembered route for exactly this desk and this adapter choice, when it is still fresh.
///
/// A route belongs to one console and one choice of adapter: another address, another adapter or
/// strict mode are other routes, and a guess here would write through the wrong interface.
fn remembered_route(
    wing_ip: Ipv4Addr,
    preferred: Option<&str>,
    strict: bool,
) -> Option<KnownWingRoute> {
    known_wing_route_slot()
        .lock()
        .ok()
        .and_then(|slot| slot.clone())
        .filter(|known| {
            known.wing_ip == wing_ip
                && known.strict == strict
                && known.preferred.as_deref() == preferred
                && known.learned_at.elapsed() < ROUTE_MEMORY_TTL
        })
}

/// The route an operator action should use: the remembered one when there is one, and one discovery
/// exchange when there is not.
///
/// A remembered route is only used together with the model remembered for that desk, because the
/// model is what the step rules are checked against and answering those rules from a guess is the
/// defect this path exists to avoid. A stale answer — the adapter gone, a console on another network
/// — falls through to a fresh exchange instead of failing the action.
fn action_route_for(
    wing_ip: Ipv4Addr,
    preferred: Option<&str>,
    strict: bool,
) -> Result<(Option<Ipv4Addr>, DeskModel), String> {
    if let Some(known) = remembered_route(wing_ip, preferred, strict) {
        if let Some(model) = know_desk_model(Some(wing_ip)) {
            // The socket is bound here, not only remembered: an adapter that has gone away must fail
            // now, before a write is attempted through it.
            let bound = match known.local_ip {
                Some(local_ip) => UdpHub::bind_ipv4(local_ip, 0),
                None => UdpHub::bind(0),
            };
            if bound.is_ok() {
                return Ok((known.local_ip, model));
            }
            forget_wing_route();
        }
    }
    let route = probe_wing_route(wing_ip, preferred, strict)?;
    let model = DeskModel::from_discovery_reply(&String::from_utf8_lossy(&route.reply));
    remember_desk_model(wing_ip, model);
    remember_wing_route(wing_ip, preferred, strict, route.local_ip);
    Ok((route.local_ip, model))
}

/// A socket bound where the route says the desk answers. Cheap (microseconds) and fresh per action.
fn action_hub_for(local_ip: Option<Ipv4Addr>) -> Result<UdpHub, String> {
    match local_ip {
        Some(ip) => UdpHub::bind_ipv4(ip, 0),
        None => UdpHub::bind(0),
    }
    .map_err(|error| format!("OSC UDP bind failed: {error}"))
}

/// All directly admitted runs, including preparations still resolving their route.
/// A finished run removes only its own flag; PANIC and Stop raise every live flag.
static ACTIVE_TEST_ACTION_CANCEL: OnceLock<Mutex<Vec<Arc<AtomicBool>>>> = OnceLock::new();
fn active_test_action_slot() -> &'static Mutex<Vec<Arc<AtomicBool>>> {
    ACTIVE_TEST_ACTION_CANCEL.get_or_init(|| Mutex::new(Vec::new()))
}
fn register_test_action_run(cancel: Arc<AtomicBool>) {
    active_test_action_slot().lock().unwrap_or_else(|e| e.into_inner()).push(cancel);
}
fn clear_test_action_run(cancel: &Arc<AtomicBool>) {
    active_test_action_slot().lock().unwrap_or_else(|e| e.into_inner())
        .retain(|active| !Arc::ptr_eq(active, cancel));
}
fn cancel_active_test_action() -> bool {
    let slot = active_test_action_slot().lock().unwrap_or_else(|e| e.into_inner());
    let mut stopped = false;
    for cancel in slot.iter() { stopped |= !cancel.swap(true, Ordering::SeqCst); }
    stopped
}

#[derive(Default)]
struct ActionSession {
    destination: Option<Ipv4Addr>,
    stop: Option<Arc<AtomicBool>>,
    generation: u64,
    macros: std::collections::HashMap<String, ShowActionRuntime>,
}
static ACTION_SESSION: OnceLock<Mutex<ActionSession>> = OnceLock::new();
fn action_session() -> &'static Mutex<ActionSession> {
    ACTION_SESSION.get_or_init(|| Mutex::new(ActionSession::default()))
}
struct ActionLease {
    stream_stop: Arc<AtomicBool>,
    cancel: Arc<AtomicBool>,
    generation: u64,
}
impl ActionLease {
    fn admit(destination: Ipv4Addr) -> Result<Self, String> {
        let session = action_session().lock().map_err(|_| "The live session is unavailable".to_string())?;
        let stop = session.stop.as_ref().filter(|stop| !stop.load(Ordering::SeqCst))
            .ok_or_else(|| "The live session has stopped; reconnect before sending".to_string())?;
        if session.destination != Some(destination) {
            return Err("The requested destination differs from the connected console; reconnect to that destination before sending".to_string());
        }
        let cancel = Arc::new(AtomicBool::new(false));
        // Admission and stop share the session lock. A stop during route discovery
        // raises these flags, and a later reconnect cannot revive this lease.
        register_test_action_run(cancel.clone());
        Ok(Self { stream_stop: stop.clone(), cancel, generation: session.generation })
    }
}
impl Drop for ActionLease {
    fn drop(&mut self) { clear_test_action_run(&self.cancel); }
}

/// Live Safe Mode as the backend enforces it (audit 2026-09-24, open item 3): the padlock lived only
/// in the webview, so a hand-edited `.wcz`, a library file dropped on disk or an import could be
/// compiled and sent while a session ran. The window owns the switch and mirrors its effective state
/// here by a command that would set it; every command that can start or change live work asks
/// `refuse_live_change` before doing anything.
///
/// **The flag is never enabled in a shipped build, and that is now a decision.** The only command that
/// wrote it (`set_live_safe_mode`) was called by nothing, so `refuse_live_change` can never refuse: the
/// operator's Live Safe Mode is enforced by the window, which refuses the twelve library and draft actions
/// plus arming, sending a test action and firing a macro by hand, and which stays on across a reconnect.
///
/// Arming this flag was considered and rejected on 2026-10-02. The refusal list the operator documents
/// describe — a Shoot, Fire Macro, a raw message — would include the toggles an operator sends during the
/// show, so an armed padlock would refuse the performance itself at the worst possible moment. The risk the
/// lock exists for (editing a running show by accident) is a *window* risk and the window covers it, and
/// nothing reaches a console without a live session because that gate is in the backend. The seam stays
/// here, test-only, because these are the tests that pin the refusal wording; whoever wires a second client
/// to the backend will want it.
#[derive(Default)]
struct LiveSafetyState {
    live_safe_mode: AtomicBool,
}

impl LiveSafetyState {
    /// Stores the padlock and reports the state it stored.
    ///
    /// **Test-only today**, and that is the finding: the command that used to call it
    /// (`set_live_safe_mode`) was invoked by nothing, so in a shipped build this flag can never be true and
    /// `refuse_live_change` can never refuse — the operator's Live Safe Mode is enforced by the window.
    /// The tests below use it to pin the refusal wording and the way out, which is why it stays; wiring it
    /// for production, and deciding exactly what it should block, is Phase 4 of
    /// `docs/DEFINITIVE_VERSION_PLAN_2026-10-02.md`.
    #[cfg(test)]
    fn set(&self, enabled: bool) -> bool {
        self.live_safe_mode.store(enabled, Ordering::SeqCst);
        enabled
    }

    fn enabled(&self) -> bool {
        self.live_safe_mode.load(Ordering::SeqCst)
    }

    /// The one refusal every live command starts with. The wording names the action and the way out,
    /// so the operator can tell this block from a validation failure.
    fn refuse_live_change(&self, action: &str) -> Result<(), String> {
        if !self.enabled() {
            return Ok(());
        }
        Err(format!(
            "Live Safe Mode is on: {action} is blocked while a session is live. Disconnect first, or turn Live Safe Mode off in Settings."
        ))
    }
}

#[derive(Default)]
struct ActiveMeterChannelState {
    sender: Option<std::sync::mpsc::Sender<Vec<CustomMeterItemDto>>>,
    owner: Option<Arc<AtomicBool>>,
    pending: Option<Vec<CustomMeterItemDto>>,
    sources: HashMap<String, Vec<CustomMeterItemDto>>,
}

impl ActiveMeterChannelState {
    fn update(&mut self, source: &str, meters: Vec<CustomMeterItemDto>) {
        let source = source.trim();
        let source = if source.is_empty() { "dock" } else { source };
        if meters.is_empty() {
            self.sources.remove(source);
        } else {
            self.sources.insert(source.to_string(), meters);
        }
        let meters = self.combined_meters();
        if let Some(sender) = &self.sender {
            if sender.send(meters.clone()).is_ok() {
                return;
            }
            self.sender = None;
            self.owner = None;
        }
        self.pending = Some(meters);
    }

    /// Which windows hold a watchlist right now, by source name (`dock`, `meter-popup`).
    ///
    /// `get_stream_state()` publishes them so a window can see whether its own watchlist is
    /// registered — an orphaned `meter-popup` after the bridge closed was invisible before (master
    /// plan 2026-09-22, §5.2 item 30).
    fn source_names(&self) -> Vec<String> {
        self.sources.keys().cloned().collect()
    }

    fn combined_meters(&self) -> Vec<CustomMeterItemDto> {
        let mut source_names = self.sources.keys().collect::<Vec<_>>();
        source_names.sort();
        let mut seen = HashSet::new();
        let mut combined = Vec::new();
        for source in source_names {
            if let Some(meters) = self.sources.get(source) {
                for meter in meters {
                    if seen.insert(meter.key.clone()) {
                        combined.push(meter.clone());
                    }
                }
            }
        }
        combined
    }

    fn register(&mut self, owner: Arc<AtomicBool>, sender: std::sync::mpsc::Sender<Vec<CustomMeterItemDto>>) {
        if owner.load(Ordering::Relaxed) {
            return;
        }
        if let Some(meters) = self.pending.take() {
            let _ = sender.send(meters);
        }
        self.owner = Some(owner);
        self.sender = Some(sender);
    }

    fn clear_if_owner(&mut self, owner: &Arc<AtomicBool>) {
        if self.owner.as_ref().is_some_and(|active| Arc::ptr_eq(active, owner)) {
            self.sender = None;
            self.owner = None;
        }
    }
}

/// Why a paced OSC send did not happen. The distinction matters on the stream
/// thread: an operator stop must end the session, while a saturated queue or a
/// socket error must degrade instead of aborting a live stream. Previously every
/// failure propagated with `?`, so a burst of macro traffic could kill the meter
/// stream mid-show.
#[derive(Debug, Clone, PartialEq, Eq)]
enum OscSendError {
    Cancelled,
    QueueFull,
    LockPoisoned,
    Transport(String),
}

impl std::fmt::Display for OscSendError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Cancelled => write!(formatter, "OSC send cancelled"),
            Self::QueueFull => write!(formatter, "OSC send queue full (60 packets/s limit)"),
            Self::LockPoisoned => write!(formatter, "OSC rate limiter lock poisoned"),
            Self::Transport(message) => write!(formatter, "OSC send failed: {message}"),
        }
    }
}

impl From<OscSendError> for String {
    fn from(error: OscSendError) -> Self {
        error.to_string()
    }
}

fn reserve_osc_send(next: &mut Instant, now: Instant) -> Result<Instant, OscSendError> {
    let send_at = (*next).max(now);
    if send_at.duration_since(now) > OSC_MAX_QUEUE_DELAY {
        return Err(OscSendError::QueueFull);
    }
    *next = send_at + OSC_SEND_INTERVAL;
    Ok(send_at)
}

fn stream_timed_out(started: Instant, last_rx: Option<Instant>, now: Instant, timeout: Duration) -> bool {
    now.duration_since(last_rx.unwrap_or(started)) > timeout
}

/// Whether **anything** has arrived from the console recently enough to call the link alive.
///
/// A meter subscription that has gone quiet is a fact about meters, not about the link: the desk can
/// answer identity probes and OSC state while sending no meter frames at all. Only when nothing has
/// arrived is the session over. Pinned by `traffic_recently_decides_whether_a_meter_stall_is_a_link_loss`.
fn traffic_is_recent(last_rx: Option<Instant>, now: Instant, timeout: Duration) -> bool {
    last_rx
        .map(|at| now.checked_duration_since(at).map(|gap| gap <= timeout).unwrap_or(true))
        .unwrap_or(false)
}

/// Sends one packet **now**, without waiting for the paced queue, and keeps the queue's own spacing.
///
/// The global limiter (`send_rate_limited_osc`, one packet per `OSC_SEND_INTERVAL`) exists to keep a
/// burst — a fade's 128 packets, a macro storm — from flooding the desk, and it is right for those. An
/// operator's toggle is not a burst: it is one packet whose whole value is that the desk acts when the
/// hand moved, so it must not sit behind up to `OSC_MAX_QUEUE_DELAY` (1 s) of queued automation. The
/// reservation is still advanced by one interval, so the paced sends keep their rate and the desk still
/// sees at most one packet per interval on average.
///
/// Used for the native toggle only (Maillot 3.1.0, "Special case: Toggle", 782-789); every other write
/// keeps the paced path.
fn send_immediate_osc(
    hub: &UdpHub,
    packet: &[u8],
    target: &str,
    stream_stop: Option<&Arc<AtomicBool>>,
    action_stop: Option<&Arc<AtomicBool>>,
) -> Result<usize, OscSendError> {
    send_immediate_osc_when(hub, packet, target, || {
        !stream_stop.is_some_and(|flag| flag.load(Ordering::Relaxed))
            && !action_stop.is_some_and(|flag| flag.load(Ordering::Relaxed))
    })
}

fn send_immediate_osc_when(
    hub: &UdpHub, packet: &[u8], target: &str, allowed: impl Fn() -> bool,
) -> Result<usize, OscSendError> {
    if !allowed() { return Err(OscSendError::Cancelled); }
    let now = Instant::now();
    {
        let mut next = OSC_NEXT_SEND
            .get_or_init(|| Mutex::new(now))
            .lock()
            .map_err(|_| OscSendError::LockPoisoned)?;
        // Never move the reservation backwards: a later reservation must not overlap a queued send.
        *next = (*next).max(now) + OSC_SEND_INTERVAL;
    }
    // Panic/Disconnect can arrive while this sender waits for the reservation.
    if !allowed() { return Err(OscSendError::Cancelled); }
    hub.send_to(packet, target)
        .map_err(|error| OscSendError::Transport(format!("to {target}: {error}")))
}

fn send_rate_limited_osc(
    hub: &UdpHub,
    packet: &[u8],
    target: &str,
    stream_stop: Option<&Arc<AtomicBool>>,
    action_stop: Option<&Arc<AtomicBool>>,
) -> Result<usize, OscSendError> {
    let now = Instant::now();
    let send_at = {
        let mut next = OSC_NEXT_SEND
            .get_or_init(|| Mutex::new(now))
            .lock()
            .map_err(|_| OscSendError::LockPoisoned)?;
        reserve_osc_send(&mut *next, now)?
    };
    while Instant::now() < send_at {
        if stream_stop.is_some_and(|flag| flag.load(Ordering::Relaxed))
            || action_stop.is_some_and(|flag| flag.load(Ordering::Relaxed))
        {
            return Err(OscSendError::Cancelled);
        }
        thread::sleep(Duration::from_millis(2));
    }
    if stream_stop.is_some_and(|flag| flag.load(Ordering::Relaxed))
        || action_stop.is_some_and(|flag| flag.load(Ordering::Relaxed))
    {
        return Err(OscSendError::Cancelled);
    }
    hub.send_to(packet, target)
        .map_err(|error| OscSendError::Transport(format!("to {target}: {error}")))
}

/// Sends an argument-less leaf read (Maillot 3.1.0, "Reading (Get) Parameter and
/// Node data") when the global OSC limiter has a free slot right now. Returns
/// true only when a packet was actually sent, so the caller can pace the next
/// refresh. Errors are swallowed on purpose: a refresh must never abort a live
/// stream, and the next step retries the same address.
/// The refresh is paced by its caller (`OSC_STATE_REFRESH_STEP`), so it is allowed to send even when
/// the limiter has a slot reserved for a queued ramp step: a condition must not be evaluated against
/// state nobody has confirmed for seconds. It must not move the limiter backwards while doing so —
/// that would let a later reservation overlap an already queued send — so `next` only ever moves
/// forward, and the caller gets its slot when it comes.
fn reserve_refresh_slot(next: &mut Instant, now: Instant) {
    if now >= *next {
        *next = now + OSC_SEND_INTERVAL;
    }
}

fn try_send_osc_read(hub: &UdpHub, address: &str, target: &str) -> bool {
    let Ok(packet) = encode_message(address, &[]) else {
        return false;
    };
    let now = Instant::now();
    let Ok(mut next) = OSC_NEXT_SEND.get_or_init(|| Mutex::new(now)).lock() else {
        return false;
    };
    reserve_refresh_slot(&mut next, now);
    drop(next);
    hub.send_to(&packet, target).is_ok()
}

/// True when an action stopped because someone asked it to: the operator pressed
/// panic stop, or the stream ended (network timeout, meter stall, disconnect) and
/// pending actions were cancelled. Either way the outcome is `aborted`, never
/// `failed`. The old guard required `action_stop && !stream_stop`, so a panic stop
/// reported every interrupted macro as an error and inflated the failure counter,
/// which tells the operator that a macro broke when it was stopped on purpose.
fn action_outcome_was_deliberate(
    action_stop: &Arc<AtomicBool>,
    stream_stop: &Arc<AtomicBool>,
) -> bool {
    action_stop.load(Ordering::Relaxed) || stream_stop.load(Ordering::Relaxed)
}

/// Sends a subscription or priming packet from the stream thread and records the
/// outcome. An operator stop must end the session, but a saturated OSC queue or a
/// transient socket error must not: those are degraded and traced, because the
/// periodic state refresh keeps conditions correct even while the change-event
/// subscription is unavailable. Returns false when the packet was not sent.
fn send_stream_osc_or_degrade(
    app: &tauri::AppHandle,
    hub: &UdpHub,
    target: &str,
    packet: &[u8],
    address: &str,
    summary: &str,
    stop: &Arc<AtomicBool>,
) -> Result<bool, String> {
    match send_rate_limited_osc(hub, packet, target, Some(stop), None) {
        Ok(_) => {
            emit_osc_trace(app, "tx", address, vec![], summary, target);
            Ok(true)
        }
        Err(OscSendError::Cancelled) => Err("OSC stream stopped by operator".to_string()),
        Err(error) => {
            emit_osc_trace(
                app,
                "tx",
                address,
                vec![],
                &format!("{summary} · not sent: {error}"),
                target,
            );
            Ok(false)
        }
    }
}

/// The meter channel state, recovering from a poisoned lock instead of dropping the update.
///
/// Eight call sites used `if let Ok(…)` on this lock, so a panic while it was held silently discarded the
/// operator's watchlist change — no trace, no error (audit 2026-10-02). The state is a plain struct of
/// `Option`s and a `HashMap`, so the inner value is safe to recover; this is the same recovery
/// `with_osc_trace_budget` and `BackendState::snapshot` already use.
fn active_meter_channel_slot_recover() -> std::sync::MutexGuard<'static, ActiveMeterChannelState> {
    active_meter_channel_slot()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

fn active_meter_channel_slot() -> &'static Mutex<ActiveMeterChannelState> {
    ACTIVE_METER_CHANNEL.get_or_init(|| Mutex::new(ActiveMeterChannelState::default()))
}

