#[serde(rename_all = "camelCase")]
struct PluginParameterDto {
    /// The OSC name under the section, e.g. `1-thr` on `/ch/1/gate/1-thr`.
    key: &'static str,
    label: String,
    arg_kind: &'static str,
    value_kind: &'static str,
    #[serde(skip_serializing_if = "Option::is_none")]
    unit: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    min_value: Option<f64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    max_value: Option<f64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    step: Option<f64>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    options: Vec<String>,
    off_label: Option<&'static str>,
    on_label: Option<&'static str>,
    /// The comparators that make sense for this value kind, from the catalogue's one table
    /// (`wing_core::targets::operators_for_value_kind`). An FX slot's parameters are watches as well
    /// as targets (`/fx/<slot>/<name>`, 2940-2942), and the window builds its comparison list from
    /// this, so the same field a catalogue row carries is carried here.
    operators: Vec<&'static str>,
    /// The appendix's own words: the spec plus its description, so the UI can show the source.
    value_hint: String,
}

/// Turns one appendix spec into the catalogue's editing vocabulary.
///
/// `console_name` is the name the console really answers under, which is not always the row the PDF
/// printed: the STD table shows band 6's Q as `7q` while the leaf is `/eq/6q` (Maillot 3.1.0, the
/// band digit mangled on extraction; routing tables 2434, 2605, 2775). The name is the row's only
/// identity, so it is what the editor must offer — a `7q` target resolves to nothing.
fn plugin_parameter_dto(
    console_name: &'static str,
    parameter: &wing_core::plugin_models::PluginParameter,
) -> PluginParameterDto {
    use wing_core::plugin_spec::{parse_plugin_spec, PluginValueKind};
    let spec = parse_plugin_spec(parameter.spec);
    let step = match (spec.min, spec.max, spec.steps) {
        (Some(min), Some(max), Some(steps)) if steps > 1 => Some((max - min) / f64::from(steps - 1)),
        _ => None,
    };
    // The kind and the argument kind come from `plugin_spec`, which is also what the watch rules of a
    // model-qualified key (`fx:lc`) are built from: one mapping for the editor and the validator, so
    // the window can never offer a comparison the backend refuses.
    let value_kind = spec.catalogue_value_kind();
    let arg_kind = spec.catalogue_arg_kind();
    let label = match &spec.description {
        Some(description) if !description.is_empty() => {
            format!("{console_name} · {description}")
        }
        _ => console_name.to_string(),
    };
    let value_hint = match &spec.description {
        Some(description) if !description.is_empty() => {
            format!("{} ({})", parameter.spec, description)
        }
        _ => parameter.spec.to_string(),
    };
    let toggle = spec.kind == PluginValueKind::Toggle;
    PluginParameterDto {
        key: console_name,
        label,
        arg_kind,
        value_kind,
        unit: spec.unit,
        min_value: spec.min,
        max_value: spec.max,
        step,
        options: spec.options,
        off_label: if toggle { Some("Off") } else { None },
        on_label: if toggle { Some("On") } else { None },
        operators: wing_core::targets::operators_for_value_kind(value_kind).to_vec(),
        value_hint,
    }
}

