fn normalize_comparator(operator: String) -> String {
    match operator.trim() {
        "==" | "!=" | ">" | "<" => operator.trim().to_string(),
        ">=" => ">".to_string(),
        "<=" => "<".to_string(),
        _ => ">".to_string(),
    }
}

fn normalize_trigger_edge_mode(mode: String) -> String {
    match mode.trim().to_ascii_lowercase().as_str() {
        "off" | "falling" => "off".to_string(),
        "on_off" | "both" | "toggle" => "on_off".to_string(),
        _ => "on".to_string(),
    }
}

fn normalize_macro_overlap_strategy(strategy: String) -> String {
    match strategy.trim().to_ascii_lowercase().as_str() {
        "restart" | "queue_one" | "concurrent" => strategy.trim().to_ascii_lowercase(),
        _ => "drop".to_string(),
    }
}

fn normalize_logical_operator(operator: String) -> String {
    if operator.trim().eq_ignore_ascii_case("OR") {
        "OR".to_string()
    } else {
        "AND".to_string()
    }
}

fn normalize_conditions(conditions: Vec<ShowConditionDto>) -> Vec<ShowConditionDto> {
    conditions
        .into_iter()
        .take(16)
        .map(|condition| ShowConditionDto {
            label: non_empty_or(condition.label, default_condition_label()),
            target_category: non_empty_or(condition.target_category, default_trigger_category()),
            target_ids: non_empty_or(condition.target_ids, default_trigger_ids()),
            target_parameter: non_empty_or(condition.target_parameter, default_trigger_parameter()),
            send_id: condition.send_id.filter(|send_id| *send_id > 0),
            target_model: normalize_target_model(condition.target_model),
            operator: normalize_comparator(condition.operator),
            value: condition.value.trim().to_string(),
            enabled: condition.enabled,
        })
        .collect()
}

fn trigger_policy_from_config(config: &ShowRunnerConfigDto) -> MeterTriggerPolicy {
    normalize_trigger_policy(
        config.trigger_meter_mode.clone(),
        config.trigger_meter_cooldown_ms,
        config.trigger_meter_rearm_db,
        config.trigger_meter_dwell_ms,
        config.trigger_meter_stale_after_ms,
    )
}

fn normalize_trigger_policy(
    mode: String,
    cooldown_ms: u64,
    rearm_db: f32,
    dwell_ms: u64,
    stale_after_ms: u64,
) -> MeterTriggerPolicy {
    MeterTriggerPolicy {
        mode: if normalize_trigger_meter_mode(mode) == "level" {
            MeterTriggerMode::Level
        } else {
            MeterTriggerMode::Transient
        },
        cooldown_ms: cooldown_ms.min(2_000),
        rearm_db: if rearm_db.is_finite() {
            rearm_db.clamp(0.1, 24.0)
        } else {
            default_trigger_meter_rearm_db()
        },
        dwell_ms: dwell_ms.min(1_000),
        stale_after_ms: stale_after_ms.clamp(250, 10_000),
    }
}

