    /// The window reads `category.subgroup` off this JSON and writes it onto each `<option>`
    /// (`setCategoryOptions` → `data-subgroup` → the heading `dropdown.js` draws), so the key has to
    /// travel: a rename or a dropped field would leave the long category lists flat again with nothing
    /// failing on the Rust side. The two families Maillot lists are the ones that carry it.
    #[test]
    fn the_category_json_carries_the_second_level_of_the_list() {
        let sources: Vec<TargetCategoryDto> = target_categories()
            .iter()
            .filter(|category| category.group == "Sources")
            .map(|category| category_info_to_dto_for_model(category, DeskModel::Unknown))
            .collect();
        assert_eq!(sources.len(), 16, "the input sources of Maillot 1955-1965");
        let json = serde_json::to_value(&sources[0]).expect("a catalogue row must serialize");
        assert!(
            json.get("subgroup").is_some(),
            "the window reads this key, so it cannot be renamed away: {json}"
        );
        assert!(
            sources.iter().all(|row| !row.subgroup.is_empty()),
            "every source family names its second level"
        );
        let outputs: Vec<TargetCategoryDto> = target_categories()
            .iter()
            .filter(|category| category.group == "Outputs")
            .map(|category| category_info_to_dto_for_model(category, DeskModel::Unknown))
            .collect();
        assert_eq!(outputs.len(), 11, "the output feeds of Maillot 1844-1846");
        assert!(outputs.iter().all(|row| !row.subgroup.is_empty()));
        // A group that reads in one go says so with an empty string, never with a made-up level.
        let channels = target_categories()
            .iter()
            .find(|category| category.key == "ch")
            .map(|category| category_info_to_dto_for_model(category, DeskModel::Unknown))
            .expect("the channel family");
        assert_eq!(channels.subgroup, "");
    }

    #[test]
    fn live_meter_values_maps_each_display_to_its_own_event() {
        // The lookup table must key on family/device/index, so two meters on the same device get
        // their own value instead of the first match in the frame.
        let display = |index: u8, slot: usize, key: &str| MeterDisplaySpec {
            label: key.to_string(),
            address: format!("/meters/ch/{index}"),
            runtime_address: MeterAddress {
                family: "ch",
                device_id: None,
                index,
                value_slot: slot,
            },
            key: Some(key.to_string()),
        };
        let displays = vec![display(1, 0, "ch:1"), display(2, 0, "ch:2")];
        let events = vec![
            wing_core::meters::DecodedMeterEvent {
                descriptor_index: 0,
                family: MeterFamily::Ch,
                device_id: None,
                index: 1,
                raw_values: vec![0],
                values: vec![-3.5],
            },
            wing_core::meters::DecodedMeterEvent {
                descriptor_index: 0,
                family: MeterFamily::Ch,
                device_id: None,
                index: 2,
                raw_values: vec![0],
                values: vec![-21.25],
            },
        ];

        let values = live_meter_values(&displays, &events);
        assert_eq!(values.len(), 2);
        assert_eq!(values[0].key.as_deref(), Some("ch:1"));
        assert_eq!(values[0].value, -3.5);
        assert_eq!(values[1].value, -21.25);

        // A meter with no event in this frame reads as silence, not as another meter's value.
        let missing = live_meter_values(&displays[..1], &events[1..]);
        assert_eq!(missing[0].value, -90.0);
    }

    #[test]
    fn recovery_snapshots_do_not_collide_and_are_pruned() {
        let dir = std::env::temp_dir().join(format!(
            "wing-recovery-test-{}-{}",
            std::process::id(),
            SAVE_SEQUENCE.fetch_add(1, Ordering::Relaxed)
        ));
        std::fs::create_dir_all(&dir).expect("temp dir");
        let live = dir.join("macro_library.json");
        std::fs::write(&live, "{}").expect("write live file");

        let mut names = std::collections::HashSet::new();
        for _ in 0..(RECOVERY_SNAPSHOT_KEEP + 3) {
            // Consecutive calls land in the same millisecond, which is exactly the case that used to
            // overwrite the previous snapshot.
            let path = create_recovery_snapshot(&live, "macro_library")
                .expect("snapshot")
                .expect("a path");
            assert!(
                names.insert(path.clone()),
                "every snapshot must get its own name, {} was reused",
                path.display()
            );
        }
        let remaining = std::fs::read_dir(&dir)
            .expect("read dir")
            .flatten()
            .filter(|entry| {
                entry
                    .file_name()
                    .to_str()
                    .is_some_and(|name| name.starts_with("macro_library.recovery."))
            })
            .count();
        assert_eq!(
            remaining, RECOVERY_SNAPSHOT_KEEP,
            "old snapshots must be pruned so they cannot accumulate forever"
        );
        assert!(live.exists(), "pruning must not touch the live file");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn osc_send_slots_are_spaced_and_bounded() {
        let now = Instant::now();
        let mut next = now;
        let first = reserve_osc_send(&mut next, now).expect("first slot");
        let second = reserve_osc_send(&mut next, now).expect("second slot");
        assert_eq!(first, now);
        assert_eq!(second.duration_since(first), OSC_SEND_INTERVAL);
        for _ in 0..57 {
            reserve_osc_send(&mut next, now).expect("within one-second queue");
        }
        assert!(reserve_osc_send(&mut next, now).is_err());
    }

    #[test]
    fn stream_timeout_applies_before_first_packet_and_after_last_packet() {
        let started = Instant::now();
        let timeout = Duration::from_millis(2000);
        assert!(!stream_timed_out(started, None, started + timeout, timeout));
        assert!(stream_timed_out(started, None, started + timeout + Duration::from_millis(1), timeout));
        let last_rx = started + Duration::from_millis(1500);
        assert!(!stream_timed_out(started, Some(last_rx), started + timeout + Duration::from_millis(1), timeout));
        assert!(stream_timed_out(started, Some(last_rx), last_rx + timeout + Duration::from_millis(1), timeout));
    }

    #[test]
    fn json_save_replaces_atomically_and_keeps_previous_copy() {
        let unique = SAVE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!("wing-desktop-save-{}-{unique}", std::process::id()));
        let path = dir.join("library.json");
        write_json_with_recovery(&path, "{\"version\":1}").expect("initial write");
        write_json_with_recovery(&path, "{\"version\":2}").expect("replacement");
        assert_eq!(fs::read_to_string(&path).expect("current"), "{\"version\":2}");
        assert_eq!(fs::read_to_string(path.with_extension("json.bak")).expect("backup"), "{\"version\":1}");
        fs::remove_dir_all(dir).expect("remove test directory");
    }

    #[test]
    fn a_failed_recovery_copy_preserves_the_current_json_and_cleans_its_temporary() {
        let unique = SAVE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!("wing-save-failure-{}-{unique}", std::process::id()));
        fs::create_dir_all(&dir).unwrap();
        let path = dir.join("library.json");
        let original = "{\"version\":1,\"macros\":[\"keep me\"]}";
        fs::write(&path, original).unwrap();
        // A directory at the backup path forces failure without assuming user privileges or filling a disk.
        let backup = path.with_extension("json.bak");
        fs::create_dir(&backup).unwrap();
        fs::write(backup.join("keep"), "untouched").unwrap();
        let error = write_json_with_recovery(&path, "{\"version\":2}").expect_err("a failed backup must refuse replacement");
        assert!(error.contains("create recovery copy"), "the failed operation must be reported: {error}");
        assert_eq!(fs::read_to_string(&path).unwrap(), original, "a refused save must retain every original byte");
        assert_eq!(fs::read_to_string(backup.join("keep")).unwrap(), "untouched");
        let leftovers: Vec<_> = fs::read_dir(&dir).unwrap().map(|entry| entry.unwrap().file_name())
            .filter(|name| name.to_string_lossy().ends_with(".tmp")).collect();
        assert!(leftovers.is_empty(), "failed recovery copy must clean its temporary: {leftovers:?}");
        fs::remove_dir_all(&dir).unwrap();
    }

