    #[test]
    // Needs a real console: without `LIVE_WING_TEST` it returns early, and a test that passes by returning
    // early is counted as coverage while asserting nothing. Ignored so `cargo test` says so out loud
    // (audit 2026-10-02, S4).
    #[ignore = "needs a real WING console: set LIVE_WING_TEST=1 and run with --ignored"]
    fn discover_wing_finds_console_on_active_network() {
        if std::env::var("LIVE_WING_TEST").is_ok() {
            let res = discover_wing(Some("192.168.1.10".to_string()), None, None).expect("discover wing");
            println!("Discovered console: name={} ip={} local={} model={} fw={}", res.name, res.ip, res.local_ip, res.model, res.firmware);
            assert!(res.reply_text.starts_with("WING,"));
            assert_eq!(res.ip, "192.168.1.10");
            let local_ip = res.local_ip.parse::<Ipv4Addr>().expect("bound IPv4 route");
            connect_native_meter("192.168.1.10".parse().unwrap(), Some(local_ip)).expect("native TCP route");
            let pinned = discover_wing(Some(res.ip.clone()), Some(res.local_interface.clone()), Some(true)).expect("pinned discovery");
            assert_eq!(pinned.local_interface, res.local_interface);
            let broadcast = discover_wing(None, Some(res.local_interface.clone()), Some(true)).expect("broadcast discovery");
            assert_eq!(broadcast.ip, res.ip);
        }
    }

    #[test]
    fn network_preference_orders_and_restricts_adapters() {
        let interfaces = local_ipv4_interfaces();
        let Some(selected) = interfaces.first() else { return };
        let pinned = ordered_local_interfaces(Some(&selected.name), true).expect("pinned adapter");
        assert!(!pinned.is_empty());
        assert!(pinned.iter().all(|interface| interface.name == selected.name));
        let preferred = ordered_local_interfaces(Some(&selected.name), false).expect("preferred adapter");
        assert_eq!(preferred.first().map(|interface| interface.name.as_str()), Some(selected.name.as_str()));
        assert!(ordered_local_interfaces(Some("missing-test-adapter"), true).is_err());
        let fallback = ordered_local_interfaces(Some("missing-test-adapter"), false).expect("auto fallback");
        assert_eq!(fallback.len(), interfaces.len());
    }

    #[test]
    fn meter_watchlist_update_survives_stream_start() {
        let mut state = ActiveMeterChannelState::default();
        let meter = CustomMeterItemDto {
            group: "usb".to_string(),
            id: 46,
            label: "USB 46".to_string(),
            key: "usb:46".to_string(),
            alias: None,
        };
        state.update("dock", vec![meter.clone()]);
        let (tx, rx) = std::sync::mpsc::channel();
        let owner = Arc::new(AtomicBool::new(false));
        state.register(owner.clone(), tx);
        assert_eq!(rx.try_recv().unwrap()[0].key, "usb:46");
        let mut popup_meter = meter;
        popup_meter.id = 1;
        popup_meter.key = "ch:1".to_string();
        popup_meter.group = "ch".to_string();
        popup_meter.label = "CH 1".to_string();
        state.update("meter-popup", vec![popup_meter]);
        let combined = rx.try_recv().unwrap();
        assert_eq!(combined.len(), 2);
        assert!(combined.iter().any(|item| item.key == "usb:46"));
        assert!(combined.iter().any(|item| item.key == "ch:1"));
        state.update("meter-popup", Vec::new());
        assert_eq!(rx.try_recv().unwrap()[0].key, "usb:46");
        let previous_owner = Arc::new(AtomicBool::new(false));
        state.clear_if_owner(&previous_owner);
        assert!(state.sender.is_some());
        state.clear_if_owner(&owner);
        assert!(state.sender.is_none());
        let cancelled_owner = Arc::new(AtomicBool::new(true));
        let (cancelled_tx, _cancelled_rx) = std::sync::mpsc::channel();
        state.register(cancelled_owner, cancelled_tx);
        assert!(state.sender.is_none());
    }

    /// The bridge's red button destroys its window without going through `close_meters_window`, and
    /// `beforeunload` does not run either: the popup's watchlist stayed in the backend, subscribed to
    /// the live stream, for the rest of the session (master plan 2026-09-22, §5.2 item 30). Both
    /// closing paths release the same source, and releasing it twice is harmless.
    #[test]
    fn releasing_the_bridge_source_drops_only_the_popup_watchlist() {
        let dock = CustomMeterItemDto {
            group: "usb".to_string(),
            id: 46,
            label: "USB 46".to_string(),
            key: "usb:46".to_string(),
            alias: None,
        };
        let popup = CustomMeterItemDto {
            group: "ch".to_string(),
            id: 1,
            label: "CH 1".to_string(),
            key: "ch:1".to_string(),
            alias: None,
        };
        {
            let mut slot = active_meter_channel_slot().lock().expect("meter channel slot");
            slot.update("dock", vec![dock.clone()]);
            slot.update("meter-popup", vec![popup.clone()]);
            assert_eq!(slot.combined_meters().len(), 2);
        }

        release_meter_popup_source();

        {
            let slot = active_meter_channel_slot().lock().expect("meter channel slot");
            assert_eq!(
                slot.source_names(),
                vec!["dock".to_string()],
                "the bridge's source is gone and the dock's stays"
            );
            assert_eq!(slot.combined_meters().len(), 1);
        }
        // The red button can arrive after `close_meters_window` already released it.
        release_meter_popup_source();
        assert_eq!(
            active_meter_channel_slot()
                .lock()
                .expect("meter channel slot")
                .source_names(),
            vec!["dock".to_string()]
        );
        // Leave the global as it was found: no test may hand a watchlist to a stream that is not there.
        active_meter_channel_slot()
            .lock()
            .expect("meter channel slot")
            .update("dock", Vec::new());
    }

    /// The frames of a session carry its id (master plan 2026-09-22, §5.2 item 31): a mode switch or
    /// a reconnect leaves the old stream's last frames in flight for up to ~250 ms, and a window that
    /// cannot tell them apart paints them over the session it is already watching.
    #[test]
    fn meter_frames_and_status_carry_the_session_they_belong_to() {
        let first = begin_stream_session();
        let second = begin_stream_session();
        assert!(first >= 1, "0 means no session, so a real session is never 0");
        assert_eq!(second, first + 1, "every session gets its own id");
        assert_eq!(current_stream_session_id(), second);

        let frame = UsbMeterFrameDto {
            session_id: first,
            packet_index: 7,
            usb1: -20.0,
            usb2: -21.0,
            usb3: -22.0,
            meters: Vec::new(),
            trigger_hit: None,
            action_sent: None,
        };
        let json = serde_json::to_value(&frame).expect("frame serializes");
        assert_eq!(
            json.get("session_id").and_then(|value| value.as_u64()),
            Some(first),
            "the window reads the frame's own id: {json}"
        );
        // A frame of the session just left is not the current one: that comparison is all the window
        // has to do to drop it.
        assert_ne!(
            json.get("session_id").and_then(|value| value.as_u64()),
            Some(current_stream_session_id())
        );

        let status = serde_json::to_value(UsbStreamStatusDto {
            state: "connecting",
            message: "updating native meter subscription".to_string(),
            session_id: second,
        })
        .expect("status serializes");
        assert_eq!(
            status.get("session_id").and_then(|value| value.as_u64()),
            Some(second),
            "the status that starts a session names it: {status}"
        );
    }

    /// A binding says what is listened for and which macro fires, and the two fields that could disagree are
    /// one field on purpose: the trigger's id is the spec's.
    #[test]
    fn a_binding_carries_its_spec_and_refuses_ids_that_cannot_be_told_apart() {
        let spec = |id: &str| inter_app_midi::MidiTriggerSpec {
            trigger_id: id.to_string(),
            kind: inter_app_midi::MidiMessageKind::NoteOn,
            channel: 1,
            number: 60,
            operator: None,
            value: 0,
        };
        let settings = InterAppSettingsDto {
            schema_version: INTER_APP_SCHEMA_VERSION,
            enabled: true,
            peers: Vec::new(),
            triggers: vec![
                InterAppTriggerDto { macro_id: None, macro_index: Some(0), spec: Some(spec("midi-1")), osc: None, require: None },
                InterAppTriggerDto { macro_id: None, macro_index: Some(3), spec: Some(spec("midi-2")), osc: None, require: None },
            ],
            active: false,
        };
        assert!(settings.validate().is_ok());
        let rules = settings.midi_rules();
        assert_eq!(rules.len(), 2, "both bindings are handed to the runtime");
        assert_eq!(rules[1].spec.trigger_id, "midi-2");
        assert!(rules[1].require.is_none(), "and a binding with no condition says so");
        assert!(settings.is_active(), "the switch plus a peer is what makes it active");

        // Round trip: what is written is what is read, bindings included.
        let payload = serde_json::to_string_pretty(&settings).expect("encode");
        let read_back: InterAppSettingsDto = serde_json::from_str(&payload).expect("decode");
        assert_eq!(read_back.triggers.len(), 2);
        assert_eq!(read_back.triggers[1].macro_index, Some(3));
        assert!(read_back.validate().is_ok());

        // Two bindings with one id: the macro that fires would depend on the order of a list, so it is refused.
        let duplicated = InterAppSettingsDto {
            triggers: vec![
                InterAppTriggerDto { macro_id: None, macro_index: Some(0), spec: Some(spec("midi-1")), osc: None, require: None },
                InterAppTriggerDto { macro_id: None, macro_index: Some(1), spec: Some(spec("midi-1")), osc: None, require: None },
            ],
            ..settings.clone()
        };
        let error = duplicated.validate().expect_err("one id, one binding");
        assert!(error.contains("midi-1"), "{error}");

        // A learned trigger with no macro yet is a legitimate state: it exists, it is listed, it fires nothing.
        let draft = InterAppSettingsDto {
            triggers: vec![InterAppTriggerDto { macro_id: None, macro_index: None, spec: Some(spec("midi-9")), osc: None, require: None }],
            ..settings.clone()
        };
        assert!(draft.validate().is_ok(), "a trigger awaiting a macro is not an error");
        assert_eq!(draft.midi_rules().len(), 1);

        // And an id that is only spaces is no id at all.
        let blank = InterAppSettingsDto {
            triggers: vec![InterAppTriggerDto { macro_id: None, macro_index: None, spec: Some(spec("   ")), osc: None, require: None }],
            ..settings
        };
        assert!(blank.validate().is_err(), "an unnamed trigger cannot be looked up");
    }

    /// An OSC step is a step whose target is a message and a destination, and its rules are its own — the same
    /// shape as the MIDI step, and the same silent failure it has to avoid: no address means the compile path
    /// would drop it without a word.
    #[test]
    fn an_osc_step_carries_its_message_and_its_destination() {
        let step_from = |extra: serde_json::Value| -> ShowActionStepDto {
            let mut base = serde_json::json!({
                "label": "start the cue",
                "actionMode": "osc_send",
                "actionAddress": "",
                "actionArgKind": "",
                "actionValue": "",
                "enabled": true
            });
            for (key, value) in extra.as_object().expect("an object") {
                base[key] = value.clone();
            }
            serde_json::from_value(base).expect("a step DTO")
        };
        let message = serde_json::json!({
            "host": "127.0.0.1",
            "port": 53000,
            "address": "/cue/selected/start",
            "args": [{ "type": "int", "value": 1 }, { "type": "str", "value": "cue" }]
        });

        let good = step_from(serde_json::json!({ "osc": message }));
        assert!(action_step_has_target(&good), "an OSC step's target is its message");
        assert!(
            action_step_problems("Step 1", &good).is_empty(),
            "{:?}",
            action_step_problems("Step 1", &good)
        );

        // Each missing piece is named, so the operator knows which field to fill.
        let empty = step_from(serde_json::json!({}));
        let problems = action_step_problems("Step 1", &empty);
        assert!(problems.iter().any(|problem| problem.contains("needs the message")), "{problems:?}");
        assert!(!action_step_has_target(&empty));

        let no_host = step_from(serde_json::json!({ "osc": { "host": "  ", "port": 53000, "address": "/go" } }));
        let problems = action_step_problems("Step 1", &no_host);
        assert!(problems.iter().any(|problem| problem.contains("address it sends to")), "{problems:?}");

        let no_port = step_from(serde_json::json!({ "osc": { "host": "127.0.0.1", "port": 0, "address": "/go" } }));
        let problems = action_step_problems("Step 1", &no_port);
        assert!(problems.iter().any(|problem| problem.contains("needs a port")), "{problems:?}");

        // The module's address rules, reached through the step: a step is never a looser path to the wire than the
        // test button, and a pattern stays legitimate (QLab documents them).
        let bad_address = step_from(serde_json::json!({ "osc": { "host": "127.0.0.1", "port": 53000, "address": "nope" } }));
        let problems = action_step_problems("Step 1", &bad_address);
        assert!(problems.iter().any(|problem| problem.contains("must start with '/'")), "{problems:?}");
        let pattern = step_from(serde_json::json!({ "osc": { "host": "127.0.0.1", "port": 53000, "address": "/cue/*/armed", "args": [{ "type": "int", "value": 0 }] } }));
        assert!(
            action_step_problems("Step 1", &pattern).is_empty(),
            "a pattern is a legitimate address: {:?}",
            action_step_problems("Step 1", &pattern)
        );

        // A message on a step that does not send one is a field that does nothing.
        let console_step = serde_json::from_value::<ShowActionStepDto>(serde_json::json!({
            "label": "mute",
            "actionMode": "set",
            "actionAddress": "/ch/1/mute",
            "actionArgKind": "int",
            "actionValue": "1",
            "enabled": true,
            "osc": message
        }))
        .expect("a console step with a stray field");
        let problems = action_step_problems("Step 1", &console_step);
        assert!(problems.iter().any(|problem| problem.contains("only an OSC step")), "{problems:?}");

        // The compile path keeps it, carries the message, and reports what was sent rather than an empty column.
        let mut config = default_show_runner_config();
        config.action_mode = "osc_send".to_string();
        config.action_steps = vec![good.clone()];
        let compiled = configured_osc_action_for_config(&config).expect("one step compiles");
        assert_eq!(compiled.steps.len(), 1);
        let step = &compiled.steps[0];
        assert!(step.osc.is_some(), "the message travels with the run");
        assert_eq!(step.mode, "osc_send");
        assert!(step.address.contains("/cue/selected/start"), "the report says what will be sent: {}", step.address);
        assert!(step.address.contains("s \"cue\""), "arguments included: {}", step.address);
    }

    /// A MIDI step is a step whose target is a message, not an address — and its rules are its own.
    ///
    /// The dangerous failure this pins is silent: a MIDI step has no address, so the compile path's
    /// "a step with no target cannot be sent anywhere" filter would drop it without a word.
    #[test]
    fn a_midi_step_carries_its_message_and_is_not_checked_against_a_desk() {
        let step_from = |extra: serde_json::Value| -> ShowActionStepDto {
            let mut base = serde_json::json!({
                "label": "cue the video",
                "actionMode": "midi_send",
                "actionAddress": "",
                "actionArgKind": "",
                "actionValue": ""
            });
            for (key, value) in extra.as_object().expect("an object") {
                base[key] = value.clone();
            }
            serde_json::from_value(base).expect("a step DTO")
        };
        let message = serde_json::json!({ "kind": "note_on", "channel": 1, "number": 60, "value": 100 });

        let good = step_from(serde_json::json!({ "midi": message, "enabled": true }));
        assert!(
            action_step_has_target(&good),
            "a MIDI step has a target: without this the compile path would drop it in silence"
        );
        assert!(
            action_step_problems("Step 1", &good).is_empty(),
            "{:?}",
            action_step_problems("Step 1", &good)
        );

        // No message: refused, with a sentence that says which step and what is missing.
        let empty = step_from(serde_json::json!({}));
        let problems = action_step_problems("Step 1", &empty);
        assert!(problems.iter().any(|problem| problem.contains("needs the message")), "{problems:?}");
        assert!(!action_step_has_target(&empty), "and it is not a step to compile");

        // Out of range: the module's own validation, reached through the step, so a step cannot be a looser path
        // to the wire than the test button.
        let bad_channel = step_from(serde_json::json!({ "midi": { "kind": "note_on", "channel": 0, "number": 60, "value": 100 } }));
        let problems = action_step_problems("Step 1", &bad_channel);
        assert!(problems.iter().any(|problem| problem.contains("1 to 16")), "{problems:?}");

        // A message on a step that does not send one is a field that does nothing, which is a trap.
        let console_step = serde_json::from_value::<ShowActionStepDto>(serde_json::json!({
            "label": "mute",
            "actionMode": "set",
            "actionAddress": "/ch/1/mute",
            "actionArgKind": "int",
            "actionValue": "1",
            "enabled": true,
            "midi": message
        }))
        .expect("a console step with a stray field");
        let problems = action_step_problems("Step 1", &console_step);
        assert!(problems.iter().any(|problem| problem.contains("only a MIDI step")), "{problems:?}");

        // And the compile path keeps it: no console bytes, the message carried, and the report reading as what
        // was sent rather than an empty address.
        // The configuration comes from the application's own defaults, so this test is about the MIDI step and not
        // about keeping a JSON literal in step with the DTO (which it spent three rounds failing to do).
        let mut config = default_show_runner_config();
        config.action_mode = "midi_send".to_string();
        config.action_steps = vec![good.clone()];
        let compiled = configured_osc_action_for_config(&config).expect("one step compiles");
        assert_eq!(compiled.steps.len(), 1);
        let step = &compiled.steps[0];
        assert!(step.midi.is_some(), "the message travels with the run");
        assert_eq!(step.mode, "midi_send");
        assert!(step.address.contains("note on"), "the report says what was sent: {}", step.address);
    }

    /// The owner's screenshot, as a test: step 2 is `set Buses — Not configured — Mute` and the
    /// enable dialog said `Step 2: no action address.`. The refusal speaks the row's language now,
    /// and it is the *only* copy of it — the preflight reads it through `validate_macro_config`, so
    /// the dialog prints one line rather than one per check.
    #[test]
    fn a_step_with_no_chosen_target_is_refused_in_the_step_row_s_own_words() {
        let mut broken = default_action_step();
        broken.target_category = "bus".to_string();
        broken.target_ids = String::new();
        broken.target_parameter = "mute".to_string();
        broken.action_address = String::new();

        let problems = action_step_problems("Step 2", &broken);
        assert_eq!(problems.len(), 1, "one missing target is one reason: {problems:?}");
        let reason = &problems[0];
        assert!(reason.starts_with("Step 2: "), "the refusal names the step: {reason}");
        assert!(reason.contains("the target is not chosen"), "{reason}");
        assert!(
            reason.contains("Buses — Not configured — Mute"),
            "the refusal quotes the step row the operator is reading, labels and all: {reason}"
        );

        // The dialog shows `preflight_config`'s messages, one per line: one problem, one line.
        let mut config = default_show_runner_config();
        config.action_steps = vec![default_action_step(), broken.clone()];
        let result = preflight_config(config.clone());
        assert!(!result.ok, "the step cannot run, so it is still refused: {:?}", result.messages);
        assert!(result.messages.iter().any(|message| message == reason), "{:?}", result.messages);
        let step_lines = result
            .messages
            .iter()
            .filter(|message| message.starts_with("Step 2:"))
            .count();
        assert_eq!(step_lines, 1, "this step's reason is printed once: {:?}", result.messages);
        assert!(
            !result
                .messages
                .iter()
                .any(|message| message.contains("OSC action address is required")),
            "the preflight's second vocabulary for the same fact is gone: {:?}",
            result.messages
        );

        // The compile path is the gate a hand-edited show file cannot skip, and it refuses for the
        // same reason the dialog showed.
        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a step with no chosen target must not compile");
        assert!(error.contains("the target is not chosen"), "{error}");
        assert!(error.contains("Buses — Not configured — Mute"), "{error}");
    }

    /// "Never chosen" and "chosen and its address is gone" are different facts about a step, and the
    /// message must not blur them. The second is where a model-dependent parameter once pointed at a
    /// leaf the strip no longer runs — but the step file does not say *why* its address is empty (a
    /// model change, a hand-edited show, an import), so the reason stops at what the app can see and
    /// must not name a cause it cannot know.
    #[test]
    fn a_chosen_target_with_no_address_is_told_apart_from_one_never_chosen() {
        let mut chosen = default_action_step();
        chosen.target_category = "ch".to_string();
        chosen.target_ids = "1".to_string();
        chosen.target_parameter = "mute".to_string();
        chosen.action_address = String::new();

        let problems = action_step_problems("Step 1", &chosen);
        assert_eq!(problems.len(), 1, "{problems:?}");
        let reason = &problems[0];
        assert!(
            !reason.contains("the target is not chosen"),
            "a target the file still selects must not be called unchosen: {reason}"
        );
        assert!(reason.contains("is chosen"), "{reason}");
        assert!(
            reason.contains("Channels 1 Mute"),
            "the chosen target is quoted in the editor's labels: {reason}"
        );
        assert!(
            !reason.to_lowercase().contains("model"),
            "the app cannot see which model the strip runs, so it must not name a cause: {reason}"
        );

        // The same step with its entry field blank *is* never chosen, and says so.
        let mut never = chosen.clone();
        never.target_ids = String::new();
        let reason = action_step_problems("Step 1", &never).remove(0);
        assert!(reason.contains("the target is not chosen"), "{reason}");
        assert!(reason.contains("Channels — Not configured — Mute"), "{reason}");
    }

    /// The honest boundary of the no-address refusal, pinned so nobody has to guess it later.
    ///
    /// A model-dependent parameter (gate, dyn, EQ) exists only for the model the strip runs
    /// (AGENTS.md, WING Protocol Authority point 6), so a strip whose model changes can leave a step
    /// pointing at a name that model does not have. That step keeps a path for its address — the
    /// model decides the leaf's *name*, not the shape of the path — so it is refused by
    /// `target_model_problem`, which names the model, and never reaches the no-address message at
    /// all. The no-address message therefore does not guess a cause for an empty address: a model
    /// change, a hand-edited show, an import and a draft saved mid-edit all leave the same bytes,
    /// and the step file does not say which one it was.
    #[test]
    fn model_scoped_fades_use_the_same_argument_type_as_the_catalogue() {
        let mut config=model_parameter_step_config("ch","gate:thr",Some("GATE"));
        let step=&mut config.action_steps[0];step.action_mode="fade".into();
        step.fade_start_value=-40.0;step.fade_end_value=-20.0;step.fade_duration_ms=1000;
        assert!(action_step_problems("Step",step).is_empty(), "{:?}",action_step_problems("Step",step));
        step.target_model=Some("DEQ2".into());assert!(!action_step_problems("Step",step).is_empty());
        let mut unknown=default_action_step();unknown.target_category="custom".into();unknown.target_parameter=String::new();
        unknown.action_address="/unknown".into();unknown.action_mode="fade".into();
        assert!(!action_step_problems("Step",&unknown).is_empty());
        assert!(!wing_core::targets::value_is_continuous("number","int"));
        assert!(!wing_core::targets::value_is_continuous("number","unknown"));
    }

    #[test]
    fn a_model_dependent_step_is_refused_by_its_model_not_by_the_no_address_message() {
        // `gate:thr` is a GATE name; a DEQ2 gate has `1-thr`, not `thr` (Maillot 3.1.0 appendix).
        let config = model_parameter_step_config("ch", "gate:thr", Some("DEQ2"));
        assert!(
            !config.action_steps[0].action_address.trim().is_empty(),
            "the selector still resolves to a path, which is why this never becomes a no-address refusal"
        );

        let problems = action_step_problems("Step 1", &config.action_steps[0]);
        assert!(
            problems.iter().any(|problem| problem.contains("DEQ2")),
            "the refusal names the model that has no such parameter: {problems:?}"
        );
        assert!(
            !problems
                .iter()
                .any(|problem| problem.contains("the target is not chosen")),
            "a written address is never reported as an unchosen target: {problems:?}"
        );
    }

    /// Phase A's promise, as tests: the registry starts off and empty, it never silently loses what it
    /// cannot understand, and "active" is false unless the operator switched it on *and* a peer exists.
    #[test]
    fn the_inter_application_registry_starts_off_and_refuses_what_it_cannot_understand() {
        let fresh = default_inter_app_settings();
        assert_eq!(fresh.schema_version, INTER_APP_SCHEMA_VERSION);
        assert!(!fresh.enabled, "the feature is off until the operator says otherwise");
        assert!(fresh.peers.is_empty());
        assert!(
            !fresh.is_active(),
            "off and empty: nothing may run, and the window shows the same answer"
        );

        // A trigger bound to a macro, with no peer at all, is a configured feature: the switch alone still is
        // not (asserted just below), but a binding is something to do.
        let with_trigger_only = InterAppSettingsDto {
            enabled: true,
            triggers: vec![InterAppTriggerDto {
                macro_id: None,
                macro_index: Some(0),
                require: None,
                osc: None,
                spec: Some(inter_app_midi::MidiTriggerSpec {
                    trigger_id: "midi-1".to_string(),
                    kind: inter_app_midi::MidiMessageKind::NoteOn,
                    channel: 0,
                    number: 60,
                    operator: None,
                    value: 0,
                }),
            }],
            ..default_inter_app_settings()
        };
        assert!(with_trigger_only.is_active(), "a binding is something to do");

        // Switched on with nothing configured is still not active: an empty registry must not start a
        // listener or a MIDI client just because a checkbox is ticked.
        let switched_on_only = InterAppSettingsDto {
            enabled: true,
            ..default_inter_app_settings()
        };
        assert!(!switched_on_only.is_active());
        assert!(switched_on_only.validate().is_ok());

        // One enabled peer, and only then, is the feature active.
        let with_peer = InterAppSettingsDto {
            schema_version: INTER_APP_SCHEMA_VERSION,
            enabled: true,
            triggers: Vec::new(),
            peers: vec![InterAppPeerDto {
                id: "mixing-station".to_string(),
                kind: InterAppPeerKind::Midi,
                name: "Mixing Station".to_string(),
                host: String::new(),
                enabled: true,
                notes: String::new(),
            }],
            active: false,
        };
        assert!(with_peer.is_active());
        assert!(with_peer.validate().is_ok());

        // A disabled peer does not make it active on its own.
        let peer_off = InterAppSettingsDto {
            peers: vec![InterAppPeerDto {
                enabled: false,
                ..with_peer.peers[0].clone()
            }],
            ..with_peer.clone()
        };
        assert!(peer_off.is_active(), "the master switch plus a peer is what counts in this phase");

        // Round trip: what is written is what is read back, and `active` is not stored.
        let payload = serde_json::to_string_pretty(&with_peer).expect("encode");
        assert!(
            !payload.contains("active"),
            "the derived flag must not be written to disk: {payload}"
        );
        let read_back: InterAppSettingsDto = serde_json::from_str(&payload).expect("decode");
        assert!(!read_back.active, "a file has no opinion about being active");
        assert_eq!(read_back.peers.len(), 1);
        assert_eq!(read_back.peers[0].kind, InterAppPeerKind::Midi);

        // Refusals: each names what is wrong instead of dropping the peer quietly.
        let unknown_schema = InterAppSettingsDto {
            schema_version: 99,
            ..default_inter_app_settings()
        };
        let error = unknown_schema.validate().expect_err("an unknown schema is refused");
        assert!(error.contains("99"), "the message names the schema it saw: {error}");

        let duplicate = InterAppSettingsDto {
            peers: vec![with_peer.peers[0].clone(), with_peer.peers[0].clone()],
            ..with_peer.clone()
        };
        assert!(duplicate.validate().is_err(), "two peers with one id is a mistake");

        let nameless = InterAppSettingsDto {
            peers: vec![InterAppPeerDto {
                name: "   ".to_string(),
                ..with_peer.peers[0].clone()
            }],
            ..with_peer.clone()
        };
        assert!(nameless.validate().is_err(), "a peer with no name cannot be chosen in the interface");

        // An unknown `kind` is a parse failure, which is how a file from a future version is refused
        // rather than half-understood.
        let future_kind = r#"{"schema_version":1,"enabled":true,"peers":[{"id":"x","kind":"dante","name":"X"}]}"#;
        assert!(
            serde_json::from_str::<InterAppSettingsDto>(future_kind).is_err(),
            "a peer kind this build does not know must not be accepted"
        );
    }

    /// A stream that has already been replaced still emits once — its thread exits up to a receive timeout
    /// after `replace_active_stream` — and that terminal status must not overwrite the live session's.
    ///
    /// This is the failure the owner reported on 2026-10-02: reconnecting during a live session left the
    /// backend believing there was no session, so the console-write gate refused Shoot, Test Action and Fire
    /// Macro with "Not connected (stopped)" while the meters were flowing and the window said Live.
    #[test]
    fn a_superseded_stream_cannot_overwrite_the_current_sessions_status() {
        let state = BackendState::default();
        let (stop, session_id) = replace_active_stream();
        state.record_status_for_session(session_id, "live", "receiving WING meter frames");
        assert_eq!(state.inner.lock().expect("snapshot").state, "live");

        // The previous stream's last words, arriving after the new session is already live.
        state.record_status_for_session(
            session_id.wrapping_sub(1),
            "stopped",
            "live meter stream stopped",
        );
        assert_eq!(
            state.inner.lock().expect("snapshot").state,
            "live",
            "a superseded stream must not be able to say the current session stopped"
        );

        // The session that *is* current can still end it, and then it is believed.
        state.record_status_for_session(session_id, "stopped", "live meter stream stopped");
        assert_eq!(state.inner.lock().expect("snapshot").state, "stopped");
        stop.store(true, Ordering::Relaxed);
    }

    /// The backend's truth is recorded where the events are produced, so a window that reloads asks
    /// `get_stream_state()` and gets the same answer the events gave (master plan 2026-09-22, §5.2
    /// item 17, Milestone 1 item 9). What is asserted here is the recording itself and the DTO
    /// contract the window reads; the `AppHandle` half of the snapshot needs an application.
    #[test]
    fn the_backend_state_records_the_last_status_and_health() {
        assert!(stream_state_is_live("live") && stream_state_is_live("connecting"));
        for state in ["idle", "stopped", "error", "disconnected", "panic_stop"] {
            assert!(!stream_state_is_live(state), "{state} is not a running session");
        }

        let state = BackendState::default();
        {
            let snapshot = state.inner.lock().expect("snapshot");
            assert_eq!(snapshot.state, "idle", "nothing started: the badge reads offline");
            assert!(snapshot.message.is_empty());
            assert!(snapshot.health.is_none());
            assert!(snapshot.last_alert.is_none());
        }

        let health = MeterStreamHealthDto {
            state: "live",
            packets: 3,
            decoded_events: 2,
            trigger_hits: 1,
            packet_rate_hz: 8.0,
            byte_rate_bps: 400.0,
            last_rx_ms_ago: Some(12),
            last_renew_ms_ago: Some(20),
            last_decode_micros: 30,
            trigger_latency_samples: 1,
            trigger_latency_p50_micros: 100,
            trigger_latency_p95_micros: 100,
            trigger_latency_max_micros: 100,
            dropped_meter_count: 0,
        };
        state.record_health(&health);
        state.record_status("live", "receiving WING meter frames");
        {
            let snapshot = state.inner.lock().expect("snapshot");
            assert_eq!(snapshot.state, "live");
            assert_eq!(snapshot.message, "receiving WING meter frames");
            assert!(snapshot.health.is_some(), "a live session keeps its health");
        }

        // A stream that ends takes its health with it: a window that opens later must not be handed
        // the frozen numbers of a session that is gone (§5.2 item 19).
        state.record_status("disconnected", "no valid packets for 3.5s");
        {
            let snapshot = state.inner.lock().expect("snapshot");
            assert_eq!(snapshot.state, "disconnected");
            assert!(snapshot.health.is_none());
        }

        // The DTO the window reads: camelCase names, and `health` is `null` rather than zeroed
        // numbers, so "no session" and "a silent session" cannot be confused.
        let session_id = current_stream_session_id();
        let dto = StreamStateDto {
            state: "disconnected",
            message: "no valid packets for 3.5s".to_string(),
            session_active: false,
            session_id,
            desk_model: None,
            desk_model_known: false,
            live_safe_mode: true,
            health: None,
            meter_sources: vec!["dock".to_string()],
            meters_window_open: false,
            last_alert: None,
        };
        let json = serde_json::to_value(&dto).expect("state serializes");
        for key in [
            "state",
            "message",
            "sessionActive",
            "sessionId",
            "deskModel",
            "deskModelKnown",
            "liveSafeMode",
            "health",
            "meterSources",
            "metersWindowOpen",
            "lastAlert",
        ] {
            assert!(json.get(key).is_some(), "the window reads {key}: {json}");
        }
        assert!(json.get("health").expect("health key").is_null());
        assert_eq!(json.get("sessionId").and_then(|value| value.as_u64()), Some(session_id));
    }

    #[test]
    fn identity_probe_ignores_packets_from_another_source() {
        let receiver = UdpHub::bind_ipv4(Ipv4Addr::LOCALHOST, 0).expect("receiver");
        let sender = UdpHub::bind_ipv4(Ipv4Addr::LOCALHOST, 0).expect("sender");
        let address = receiver.local_addr().expect("receiver address");
        sender.send_to(b"WING,127.0.0.1,test", address).expect("send");
        assert!(receive_wing_identity(&receiver, Some(Ipv4Addr::new(127, 0, 0, 2)), Duration::from_millis(50)).is_none());
    }

    #[test]
    // Needs a real console: without `LIVE_WING_METER_TEST` it returns early, and a test that passes by returning
    // early is counted as coverage while asserting nothing. Ignored so `cargo test` says so out loud
    // (audit 2026-10-02, S4).
    #[ignore = "needs a real WING console: set LIVE_WING_METER_TEST=1 and run with --ignored"]
    fn live_wing_usb_meter_route_receives_native_frames() {
        if std::env::var("LIVE_WING_METER_TEST").is_err() { return; }
        let wing_ip = Ipv4Addr::new(192, 168, 1, 10);
        let route = probe_wing_route(wing_ip, None, false).expect("identity route");
        let udp = route.hub;
        let port = udp.local_addr().expect("UDP listen port").port();
        let descriptors = [MeterDescriptor::source(SOURCE_USB_DEVICE_ID)];
        let mut tcp = connect_native_meter(wing_ip, route.local_ip).expect("native TCP route");
        tcp.send_native_meter_payload(&request_payload(port, DEFAULT_REPORT_ID, &descriptors)).expect("meter request");
        let deadline = Instant::now() + Duration::from_secs(3);
        let mut buffer = [0_u8; 8192];
        let mut received_usb = false;
        while Instant::now() < deadline {
            if let Ok((len, source)) = udp.recv_once(&mut buffer, Duration::from_millis(250)) {
                if source.ip() == IpAddr::V4(wing_ip) && !buffer[..len].starts_with(b"WING,") {
                    if let Ok(events) = decode_report(DEFAULT_REPORT_ID, &descriptors, &buffer[..len]) {
                        if !events.is_empty() {
                            println!("USB meter route: local={:?}, packets=1, decoded_events={}", route.local_ip, events.len());
                            received_usb = true;
                            break;
                        }
                    }
                }
            }
        }
        assert!(received_usb, "no native USB meter frames received on selected WING route");

        // Maillot Channel 3 recommends a different report id for a different
        // collection. This mirrors a dock/popup meter update on the same TCP link.
        let updated_report_id = next_meter_report_id(DEFAULT_REPORT_ID);
        let updated_descriptors = [
            MeterDescriptor::source(SOURCE_USB_DEVICE_ID),
            MeterDescriptor::indexed(MeterFamily::Ch, vec![1]),
        ];
        tcp.send_native_meter_payload(&request_payload(
            port,
            updated_report_id,
            &updated_descriptors,
        ))
        .expect("updated meter request");
        let update_deadline = Instant::now() + Duration::from_secs(3);
        let mut received_update = false;
        while Instant::now() < update_deadline {
            if let Ok((len, source)) = udp.recv_once(&mut buffer, Duration::from_millis(250)) {
                if source.ip() == IpAddr::V4(wing_ip) {
                    if let Ok(events) = decode_report(
                        updated_report_id,
                        &updated_descriptors,
                        &buffer[..len],
                    ) {
                        if events.iter().any(|event| event.family == MeterFamily::Source)
                            && events.iter().any(|event| event.family == MeterFamily::Ch)
                        {
                            println!("Updated meter collection: report_id={updated_report_id}, decoded_events={}", events.len());
                            received_update = true;
                            break;
                        }
                    }
                }
            }
        }
        assert!(received_update, "updated native meter collection did not produce source + channel frames");

        // Every source and output device of Maillot's table 5, sized by the model the desk has just
        // announced: this is the reading that settles the counts per device (master plan 2026-09-22,
        // §12, "hardware verification"), and taking them from the family table instead would make
        // the assertion true by construction — the decoder derives an unsettled group from the frame
        // it is in.
        let desk_model = DeskModel::from_discovery_reply(&String::from_utf8_lossy(&route.reply));
        let all_io_report_id = next_meter_report_id(updated_report_id);
        let mut all_io_descriptors = (1..=16)
            .map(|device_id| MeterDescriptor::source_for_model(desk_model, device_id))
            .collect::<Vec<_>>();
        all_io_descriptors.extend(
            (1..=11).map(|device_id| MeterDescriptor::output_for_model(desk_model, device_id)),
        );
        tcp.send_native_meter_payload(&request_payload(
            port,
            all_io_report_id,
            &all_io_descriptors,
        ))
        .expect("all source/output meter request");
        let expected_events = (1..=16)
            .filter_map(|device_id| wing_core::meters::source_group_words(desk_model, device_id))
            .sum::<usize>()
            + (1..=11)
                .filter_map(|device_id| wing_core::meters::output_group_words(desk_model, device_id))
                .sum::<usize>();
        let all_io_deadline = Instant::now() + Duration::from_secs(3);
        while Instant::now() < all_io_deadline {
            if let Ok((len, source)) = udp.recv_once(&mut buffer, Duration::from_millis(250)) {
                if source.ip() == IpAddr::V4(wing_ip) {
                    if let Ok(events) = decode_report(
                        all_io_report_id,
                        &all_io_descriptors,
                        &buffer[..len],
                    ) {
                        let source_devices = events
                            .iter()
                            .filter(|event| event.family == MeterFamily::Source)
                            .filter_map(|event| event.device_id)
                            .collect::<HashSet<_>>();
                        let output_devices = events
                            .iter()
                            .filter(|event| event.family == MeterFamily::Output)
                            .filter_map(|event| event.device_id)
                            .collect::<HashSet<_>>();
                        if events.len() == expected_events
                            && source_devices.len() == 16
                            && output_devices.len() == 11
                        {
                            println!("All Maillot I/O meter groups: report_id={all_io_report_id}, decoded_events={}, sources={}, outputs={}", events.len(), source_devices.len(), output_devices.len());
                            return;
                        }
                    }
                }
            }
        }
        panic!("all source/output meter groups did not decode completely in Maillot order");
    }

