    /// The Android import carries the model too: an imported target that names one keeps it, so a
    /// `section:name` parameter is checked against the strip the payload came from, and a payload
    /// without one imports as "not known" instead of being refused.
    #[test]
    fn an_imported_android_target_keeps_its_model() {
        let raw = r#"
        {
          "schemaVersion": 3,
          "items": [
            {
              "name": "Android model macro",
              "enabled": true,
              "triggerTarget": {"type":"fixed","category":"ch","ids":"1","parameter":"dyn:thr","targetModel":"WARM","customAddress":""},
              "triggerOperator": ">",
              "triggerEdgeMode": "on",
              "triggerValue": -6,
              "actions": [
                {"type":"osc","target":{"type":"fixed","category":"ch","ids":"1","parameter":"dyn:thr","targetModel":"WARM","customAddress":""},"args":[-6]}
              ]
            },
            {
              "name": "Android macro without a model",
              "enabled": true,
              "triggerTarget": {"type":"fixed","category":"usb","ids":"1","parameter":"meter","customAddress":""},
              "triggerOperator": ">",
              "triggerEdgeMode": "on",
              "triggerValue": -18,
              "actions": [
                {"type":"osc","target":{"type":"fixed","category":"ch","ids":"1","parameter":"dyn:thr","customAddress":""},"args":[-6]}
              ]
            }
          ]
        }
        "#;
        let (parsed, _warnings) = parse_macro_library_payload(raw).unwrap();
        let library = normalize_macro_library(parsed);

        let carried = &library.macros[0];
        assert_eq!(carried.target_model.as_deref(), Some("WARM"));
        assert_eq!(carried.action_steps[0].target_model.as_deref(), Some("WARM"));
        // The model the payload carried is the one the step is refused on.
        let result = preflight_config(carried.clone());
        assert!(
            result.messages.iter().any(|message| message.starts_with("Step 1: ")
                && message.contains("WARM")),
            "{:?}",
            result.messages
        );

        // A payload without a model imports as an older file does: nothing is refused.
        let unknown = &library.macros[1];
        assert!(unknown.target_model.is_none());
        assert!(unknown.action_steps[0].target_model.is_none());
    }

    /// The name on the wire: the editor writes `targetModel` into the config it saves, so the field
    /// has to serialise and deserialise under exactly that camelCase name — and a file written
    /// before the field existed simply has none.
    #[test]
    fn the_target_model_travels_under_its_camel_case_name() {
        let mut config = model_parameter_step_config("ch", "dyn:thr", Some("COMP"));
        config.target_model = Some("COMP".to_string());
        config.conditions.push(ShowConditionDto {
            label: "gate threshold".to_string(),
            target_category: "ch".to_string(),
            target_ids: "1".to_string(),
            target_parameter: "gate:thr".to_string(),
            send_id: None,
            target_model: Some("GATE".to_string()),
            operator: ">".to_string(),
            value: "-20".to_string(),
            enabled: true,
        });

        let json = serde_json::to_value(&config).expect("the config serialises");
        assert_eq!(json["actionSteps"][0]["targetModel"], "COMP");
        assert_eq!(json["conditions"][0]["targetModel"], "GATE");
        assert_eq!(json["targetModel"], "COMP", "the trigger carries its own model too");

        let read: ShowRunnerConfigDto =
            serde_json::from_value(json).expect("and reads back under the same name");
        assert_eq!(read.target_model.as_deref(), Some("COMP"));
        assert_eq!(read.action_steps[0].target_model.as_deref(), Some("COMP"));
        assert_eq!(read.conditions[0].target_model.as_deref(), Some("GATE"));

        // An older file has no such field anywhere, and imports as "not known".
        let mut older = serde_json::to_value(default_show_runner_config()).expect("serialises");
        older["actionSteps"][0]
            .as_object_mut()
            .expect("a step object")
            .remove("targetModel");
        older.as_object_mut().expect("a config object").remove("targetModel");
        let read: ShowRunnerConfigDto =
            serde_json::from_value(older).expect("an older file still reads");
        assert!(read.target_model.is_none(), "the trigger's model is not known");
        assert!(read.action_steps[0].target_model.is_none(), "and neither is the step's");
    }

