    /// The trigger latency is what decides whether a macro feels instant on the desk, so the maths
    /// behind the reported percentiles is pinned: nearest rank (the smallest sample that is at least
    /// p% of them), which is what an operator reads as "95% of triggers finished within X".
    #[test]
    fn trigger_latency_percentiles_use_nearest_rank() {
        assert_eq!(latency_summary(&[]), (0, 0, 0, 0));
        assert_eq!(latency_summary(&[7]), (1, 7, 7, 7));

        let samples: Vec<u64> = (1..=100).collect();
        assert_eq!(latency_summary(&samples), (100, 50, 95, 100));

        // Order must not matter, and the ring keeps the last samples only.
        let shuffled = vec![900, 100, 500, 300, 700];
        assert_eq!(latency_summary(&shuffled).1, 500, "p50 is the middle sample");
        assert_eq!(latency_summary(&shuffled).2, 900, "p95 of five samples is the largest");
        assert_eq!(latency_summary(&shuffled).3, 900);

        let mut stats = StreamStats::new();
        for value in 1..=(TRIGGER_LATENCY_SAMPLES as u64 + 10) {
            stats.record_trigger_latency(value);
        }
        assert_eq!(stats.trigger_latencies.len(), TRIGGER_LATENCY_SAMPLES, "the ring is bounded");
        assert_eq!(stats.trigger_latencies.front().copied(), Some(11), "oldest samples are dropped");

        // And the summary reaches the payload the window reads (camelCase over the IPC).
        stats.record_decode_micros(42);
        stats.record_dropped_meter_datagram();
        let health = stats.health("live");
        assert_eq!(health.last_decode_micros, 42);
        assert_eq!(health.dropped_meter_count, 1, "un datagrama rechazado se cuenta de verdad");
        assert_eq!(health.trigger_latency_samples, TRIGGER_LATENCY_SAMPLES);
        assert!(health.trigger_latency_p50_micros <= health.trigger_latency_p95_micros);
        assert!(health.trigger_latency_p95_micros <= health.trigger_latency_max_micros);
        let json = serde_json::to_string(&health).expect("health serialises");
        assert!(json.contains("\"triggerLatencyP50Micros\""), "the window reads camelCase: {json}");

        // With no hits the summary is empty rather than a misleading zero.
        assert_eq!(latency_summary(&StreamStats::new().trigger_latencies.iter().copied().collect::<Vec<u64>>()), (0, 0, 0, 0));
    }

    /// The legacy `/flt/cf` path is only unambiguous with the selector metadata: with it the
    /// preflight corrects the path and says so, without it the step is refused instead of guessing
    /// whether the operator meant the high-pass or the low-pass frequency (Maillot 3.1.0 lists
    /// `/flt/lcf` and `/flt/hcf`).
    #[test]
    fn preflight_handles_the_ambiguous_legacy_filter_path() {
        let mut with_metadata = default_show_runner_config();
        with_metadata.action_steps[0].action_address = "/ch/12/flt/cf".to_string();
        with_metadata.action_steps[0].target_parameter = "hpf_freq".to_string();
        let corrected = preflight_config(with_metadata);
        assert!(corrected.ok, "metadata makes the legacy filter path resolvable");
        assert!(corrected
            .messages
            .iter()
            .any(|message| message.contains("legacy filter path corrected")));

        let mut ambiguous = default_show_runner_config();
        ambiguous.action_steps[0].action_address = "/ch/12/flt/cf".to_string();
        ambiguous.action_steps[0].target_parameter = "mute".to_string();
        let refused = preflight_config(ambiguous);
        assert!(!refused.ok, "without metadata the legacy filter path is ambiguous");
        assert!(refused
            .messages
            .iter()
            .any(|message| message.contains("ambiguous legacy /flt/cf path")));
    }

