    /// The seed a fresh step carries, which the wording test above does not pin: for a destructive
    /// command it is the difference between "format the card" and "do nothing", so
    /// `wlive_format_card` seeds 0 and its hint says so. The processing switches follow the family
    /// they belong to (`eq_on`, `peq_on` and the strip's `delay_on` all seed 1), and a state the
    /// operator arms deliberately seeds 0.
    #[test]
    fn the_desk_level_toggle_seeds_are_the_documented_ones() {
        for (key, expected) in [
            ("wlive_format_card", "0"),
            ("wlive_marker_set", "1"),
            ("aes50_clear_errors", "1"),
            ("global_start_mute", "0"),
            ("monitor_invert", "0"),
            ("monitor_eq_on", "1"),
            ("monitor_delay_on", "1"),
            ("solo_mute", "0"),
            ("solo_dim", "0"),
            ("solo_mono", "0"),
            ("solo_flip", "0"),
            ("solo_source_state", "0"),
            ("desk_lock", "0"),
        ] {
            let metadata = parameter_value_metadata(key, "int");
            assert_eq!(metadata.value_kind, "toggle", "{key} must be a toggle");
            assert_eq!(
                metadata.default_value,
                Some(expected),
                "{key} must seed {expected}"
            );
            assert!(
                metadata
                    .value_hint
                    .as_deref()
                    .is_some_and(|hint| hint.contains("0 =") || hint.contains("1 ") || hint.contains("0 (")),
                "{key} needs a hint that says which way round 0 and 1 are"
            );
        }
    }

    /// A step may only write a key its category offers as a **target**.
    ///
    /// The editor builds its step picker from that list, so the operator cannot choose a read-only
    /// key — but `watch_rule` (the union of both lists) is what the step checks used to consult, and
    /// the address of a read-only leaf resolves exactly like a writable one's. A hand-edited `.wcz`
    /// or an Android import could therefore arm a write at `/cfg/mon/1/$lvl` (read-only on the
    /// full-size WING), at `/cfg/solo/$dim`, at `/cards/$type` — a category with no target list at
    /// all — and the console would ignore it while the macro reported success.
    #[test]
    fn a_step_cannot_write_a_watch_only_key() {
        let step = |category: &str, parameter: &str, address: &str, value: &str| {
            let mut step = default_action_step();
            step.target_category = category.to_string();
            step.target_ids = "1".to_string();
            step.target_parameter = parameter.to_string();
            step.action_address = address.to_string();
            step.action_arg_kind = "int".to_string();
            step.action_value = value.to_string();
            step.action_mode = "set".to_string();
            step
        };

        for (category, parameter, address) in [
            ("monbus", "monitor_level", "/cfg/mon/1/$lvl"),
            ("monbus", "monitor_active_level", "/cfg/mon/1/$lvlact"),
            ("solocfg", "solo_source_input", "/cfg/solo/$srcsin"),
            ("solocfg", "solo_source_group", "/cfg/solo/$srcsgrp"),
            ("solocfg", "solo_source_input", "/cfg/solo/$srcsin"),
            ("aes50", "aes50_state", "/$stat/A/stat"),
            ("aes50", "aes50_errors_uncorrected", "/$stat/A/errorsu"),
            ("deskstatus", "desk_lock", "/$stat/lock"),
            ("deskstatus", "desk_ppm", "/$stat/ppm"),
            ("cards", "cards_type", "/cards/$type"),
            ("cards", "cards_version", "/cards/$ver"),
            ("wlive", "wlive_state", "/cards/wlive/1/$stat/state"),
        ] {
            let problems = action_step_problems("Step 1", &step(category, parameter, address, "1"));
            assert!(
                problems
                    .iter()
                    .any(|problem| problem.contains("read-only")),
                "{category}/{parameter} must be refused as a step: {problems:?}"
            );
        }

        // The commands and values of the same batch are the point of it: they are steps, and the
        // rule must not have caught them on the way.
        for (category, parameter, address, value) in [
            ("aes50", "aes50_clear_errors", "/$stat/A/clrerr", "1"),
            ("wlive", "wlive_control", "/cards/wlive/1/$ctl/control", "REC"),
            ("wlive", "wlive_marker_set", "/cards/wlive/1/$ctl/setmarker", "1"),
            ("monbus", "monitor_pan", "/cfg/mon/1/pan", "10"),
            ("solocfg", "solo_mute", "/cfg/solo/mute", "1"),
            ("safes", "safes_ch", "/$ctl/safes/ch", "++"),
            ("globals", "global_clock_source", "/$globals/clksrc", "INT"),
            ("deskstatus", "desk_lock", "/$stat/lock", "1"),
        ] {
            // `deskstatus` is watch-only, so the last case is the counter-example: it must be
            // refused even though the address and the value are well formed. Every other line is a
            // legitimate step and must pass.
            let problems = action_step_problems("Step 1", &step(category, parameter, address, value));
            if category == "deskstatus" {
                assert!(
                    !problems.is_empty(),
                    "deskstatus/{parameter} has no target list and must be refused"
                );
            } else {
                assert!(
                    problems.is_empty(),
                    "{category}/{parameter} is a step target: {problems:?}"
                );
            }
        }
    }

    /// Footnote 13 (Maillot 1357-1359), glued to `/cfg/mon/1/$lvl` (1316): the monitor bus level is
    /// read-only on the full-size WING and *"can be set for other devices where the actual surface
    /// control potentiometer is not present"* — which the document reads as a Rack and a Compact.
    /// **Measured on a WING Rack, 2026-09-27**: the desk ignored the write in every spelling the leaf
    /// could take (normalised integer, normalised float, dB float, dB string and the console's own
    /// spelling), so the Rack keeps the key as a watch and only the Compact — which the document
    /// grants and no desk here can measure — is offered the write. The app talks to the whole family,
    /// so the write follows the model the desk announced at discovery and not the unit this project
    /// was developed against (master plan 2026-09-22, §12, item 2).
    #[test]
    fn the_monitor_level_is_a_step_on_the_models_that_take_the_write() {
        let level_step = || {
            let mut step = default_action_step();
            step.target_category = "monbus".to_string();
            step.target_ids = "1".to_string();
            step.target_parameter = "monitor_level".to_string();
            step.action_address = "/cfg/mon/1/$lvl".to_string();
            step.action_arg_kind = "float".to_string();
            step.action_value = "-20".to_string();
            step.action_mode = "set".to_string();
            step
        };

        // The Compact takes it, and it is the only model left that does…
        assert!(
            action_step_problems_for_model("Step 1", &level_step(), DeskModel::Compact).is_empty(),
            "a Compact can set the monitor level"
        );
        // …the full-size desk does not, and the refusal cites the footnote that says why.
        let refused = action_step_problems_for_model("Step 1", &level_step(), DeskModel::Full);
        assert!(
            refused.iter().any(|problem| problem.contains("read-only")
                && problem.contains("full-size WING")),
            "a full-size WING ignores the write: {refused:?}"
        );
        // The Rack was measured to ignore it too, and the refusal says so instead of repeating the
        // document's grant (a step here reported success on a write the console never performed).
        let rack = action_step_problems_for_model("Step 1", &level_step(), DeskModel::Rack);
        assert!(
            rack.iter().any(|problem| problem.contains("read-only")
                && problem.contains("WING Rack")
                && problem.contains("2026-09-27")),
            "a Rack was measured to ignore every spelling of the write: {rack:?}"
        );
        // …and with no model announced the app withholds it and says what to do about it.
        let unknown =
            action_step_problems_for_model("Step 1", &level_step(), DeskModel::Unknown);
        assert!(
            unknown
                .iter()
                .any(|problem| problem.contains("read-only")
                    && problem.contains("discovery probe")),
            "an unannounced model cannot be granted a model-specific write: {unknown:?}"
        );

        // The rest of the node is written on every model, so the rule cannot pass by refusing all.
        for model in [
            DeskModel::Full,
            DeskModel::Rack,
            DeskModel::Compact,
            DeskModel::Unknown,
        ] {
            let mut step = level_step();
            step.target_parameter = "monitor_pan".to_string();
            step.action_address = "/cfg/mon/1/pan".to_string();
            step.action_value = "10".to_string();
            assert!(
                action_step_problems_for_model("Step 1", &step, model).is_empty(),
                "{model:?} writes the monitor pan"
            );
        }
    }

    /// The catalogue the editor builds its pickers from is the desk's, not the bench unit's: the
    /// picker offers the monitor level as a step where the document gives the write — the Compact —
    /// and withholds it on the full-size WING (footnote 13) and on the Rack, which was measured to
    /// ignore it (2026-09-27); and it offers the ids the desk really has (local inputs 8 on a
    /// full-size console and 24 on a Rack; GPIOs two on a Compact).
    #[test]
    fn the_catalogue_offers_what_the_announced_model_has() {
        let keys = |catalog: &TargetCatalogDto, category: &str| {
            catalog
                .target_parameters_by_category
                .get(category)
                .map(|parameters| {
                    parameters
                        .iter()
                        .map(|parameter| parameter.key)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default()
        };
        let count = |catalog: &TargetCatalogDto, category: &str| {
            catalog
                .categories
                .iter()
                .find(|entry| entry.key == category)
                .map(|entry| entry.count)
                .unwrap_or(0)
        };

        let full = target_catalog(Some("ngc-full".to_string()));
        let rack = target_catalog(Some("wing-rack".to_string()));
        let compact = target_catalog(Some("wing-compact".to_string()));

        assert!(
            !keys(&full, "monbus").contains(&"monitor_level"),
            "the full-size desk ignores a write to $lvl"
        );
        assert!(
            !keys(&rack, "monbus").contains(&"monitor_level"),
            "a Rack was measured to ignore every spelling of the write (2026-09-27)"
        );
        assert!(keys(&compact, "monbus").contains(&"monitor_level"));
        // It is a watch on all three: only the write is withheld (footnote 13, plus the measurement).
        for catalog in [&full, &rack, &compact] {
            assert!(catalog
                .trigger_parameters_by_category
                .get("monbus")
                .expect("the monitor bus is watchable")
                .iter()
                .any(|parameter| parameter.key == "monitor_level"));
        }

        assert_eq!(count(&full, "preamp_local"), 8, "footnote 17, Maillot 1641");
        assert_eq!(count(&rack, "preamp_local"), 24);
        assert_eq!(count(&compact, "preamp_local"), 24);
        assert_eq!(count(&compact, "gpio"), 2, "footnote 122, Maillot 11536");
        assert_eq!(count(&rack, "gpio"), 4);
        // A model nobody named, and every category the document does not size by model, keep the
        // documented count.
        let unknown = target_catalog(Some("something-else".to_string()));
        assert_eq!(count(&unknown, "preamp_local"), 24);
        assert_eq!(count(&unknown, "gpio"), 4);
        assert_eq!(count(&full, "ch"), 40);
        assert_eq!(count(&compact, "matrix"), 8);
    }

    /// A step on an id this desk does not have is a write the console ignores in silence: the local
    /// inputs are the count footnote 17 (1641) ties to the model, and a Compact's two GPIOs are
    /// footnote 122 (11536).
    #[test]
    fn a_step_on_an_id_the_desk_does_not_have_is_refused() {
        // The address the selector resolves to is part of the check: a step judged by a selector it
        // no longer owns is a different rule's business (`step_selector_owns_address`).
        let local_step = |id: &str| {
            let mut step = default_action_step();
            step.target_category = "preamp_local".to_string();
            step.target_ids = id.to_string();
            step.target_parameter = "gain".to_string();
            step.action_address = format!("/io/in/LCL/{id}/g");
            step.action_arg_kind = "float".to_string();
            step.action_value = "0".to_string();
            step.action_mode = "set".to_string();
            step
        };

        let refused = action_step_problems_for_model("Step 1", &local_step("20"), DeskModel::Full);
        assert!(
            refused.iter().any(|problem| problem.contains("footnote 17")),
            "a full-size console has eight local inputs: {refused:?}"
        );
        assert!(
            action_step_problems_for_model("Step 1", &local_step("20"), DeskModel::Rack).is_empty(),
            "a Rack has twenty-four"
        );
        assert!(
            action_step_problems_for_model("Step 1", &local_step("20"), DeskModel::Unknown).is_empty(),
            "an unannounced model keeps the documented maximum"
        );
        assert!(
            action_step_problems_for_model("Step 1", &local_step("8"), DeskModel::Full).is_empty(),
            "the ids this desk does have must pass"
        );
        let gpio = {
            let mut step = default_action_step();
            step.target_category = "gpio".to_string();
            step.target_ids = "3".to_string();
            step.target_parameter = "gpio_state".to_string();
            step.action_address = "/$ctl/gpio/3/gpstate".to_string();
            step.action_arg_kind = "int".to_string();
            step.action_value = "1".to_string();
            step.action_mode = "set".to_string();
            step
        };
        assert!(
            action_step_problems_for_model("Step 1", &gpio, DeskModel::Compact)
                .iter()
                .any(|problem| problem.contains("footnote 122")),
            "a Compact has two GPIOs"
        );
        assert!(action_step_problems_for_model("Step 1", &gpio, DeskModel::Full).is_empty());
    }

    /// The desk announces its model in the discovery reply and the app remembers it against that
    /// address — the config of another console must not borrow it. Everything model-aware reads it
    /// from there: the meter group lengths (§5.1 item 2) and the catalogue above.
    #[test]
    fn the_announced_model_is_remembered_for_the_desk_that_sent_it() {
        let desk = Ipv4Addr::new(203, 0, 113, 7);
        remember_desk_model(desk, DeskModel::Full);
        assert_eq!(know_desk_model(Some(desk)), Some(DeskModel::Full));
        assert_eq!(
            know_desk_model(Some(Ipv4Addr::new(203, 0, 113, 8))),
            None,
            "a model announced by another console is not evidence about this one"
        );
        // The config's own address is what the validator asks about.
        let mut config = default_show_runner_config();
        config.wing_ip = desk.to_string();
        assert_eq!(desk_model_for_config(&config), DeskModel::Full);
        config.wing_ip = Ipv4Addr::new(203, 0, 113, 8).to_string();
        assert_eq!(desk_model_for_config(&config), DeskModel::Unknown);

        // A reply names the model in its fourth field (Maillot 563-567), and the descriptor for the
        // local group is then sized by the console rather than by the family table.
        let reply = b"WING,203.0.113.7,a desk,ngc-full,SN,fw:release";
        assert_eq!(
            DeskModel::from_discovery_reply(&String::from_utf8_lossy(reply)),
            DeskModel::Full
        );
        let descriptors = descriptors_for_model(
            &[MeterDescriptor::source(1), MeterDescriptor::indexed(MeterFamily::Ch, vec![1])],
            DeskModel::Full,
        );
        assert_eq!(
            descriptors[0].group_words,
            wing_core::meters::GroupWords::Fixed(8)
        );
        let rack = descriptors_for_model(&[MeterDescriptor::source(1)], DeskModel::Rack);
        assert_eq!(
            rack[0].group_words,
            wing_core::meters::GroupWords::Fixed(24)
        );
    }

    /// A console that has answered discovery once is not asked again by every operator action.
    ///
    /// This is the regression an operator reported on 2026-09-27 ("a simple mute takes ages"): the
    /// Shoot, the raw send and the model reads each ran a whole `WING?` exchange before doing their
    /// work, and that exchange cost **1.302 s measured here** (one adapter plus the system-default
    /// fallback, 650 ms each) against 0.6 ms with the route remembered. There is no discovery responder
    /// in this test, so a probe here cannot succeed — the call must not try one at all.
    #[test]
    fn a_remembered_route_is_reused_without_asking_the_desk_again() {
        let desk = Ipv4Addr::new(192, 0, 2, 7);
        remember_desk_model(desk, DeskModel::Rack);
        remember_wing_route(desk, None, false, Some(Ipv4Addr::LOCALHOST));
        let started = Instant::now();
        let (local_ip, model) = action_route_for(desk, None, false).expect("the remembered route");
        let elapsed = started.elapsed();
        assert_eq!(
            local_ip,
            Some(Ipv4Addr::LOCALHOST),
            "the source address discovery found is the one the action writes from"
        );
        assert_eq!(model, DeskModel::Rack, "the model the desk announced travels with its route");
        assert!(
            elapsed < Duration::from_millis(100),
            "no discovery exchange may be paid a second time (took {elapsed:?})"
        );
        assert!(action_hub_for(local_ip).is_ok(), "the action binds its own socket there");
        forget_wing_route();
        if let Ok(mut slot) = known_desk_model_slot().lock() {
            *slot = None;
        }
    }

    /// A remembered route belongs to one desk and one adapter choice: another address, another
    /// adapter, strict mode or an answer that has gone stale is a different route, and using it would
    /// write through an interface nobody has checked.
    #[test]
    fn a_remembered_route_belongs_to_one_desk_and_one_adapter_choice() {
        let desk = Ipv4Addr::new(192, 0, 2, 8);
        remember_wing_route(desk, Some("en0"), true, Some(Ipv4Addr::LOCALHOST));
        assert!(remembered_route(desk, Some("en0"), true).is_some(), "the route it was learned for");
        assert!(remembered_route(Ipv4Addr::new(192, 0, 2, 9), Some("en0"), true).is_none(), "another desk");
        assert!(remembered_route(desk, Some("en8"), true).is_none(), "another adapter");
        assert!(remembered_route(desk, None, true).is_none(), "auto is not the same choice as a named adapter");
        assert!(remembered_route(desk, Some("en0"), false).is_none(), "strict mode is a different route");
        // A memory older than its life is not used: the cable may be somewhere else by now.
        if let Ok(mut slot) = known_wing_route_slot().lock() {
            if let Some(mut known) = slot.clone() {
                known.learned_at = Instant::now() - ROUTE_MEMORY_TTL - Duration::from_secs(1);
                *slot = Some(known);
            }
        }
        assert!(
            remembered_route(desk, Some("en0"), true).is_none(),
            "a stale route is discovered again instead of being trusted"
        );
        forget_wing_route();
    }

    /// A command leaf takes a value and nothing else.
    ///
    /// A toggle asks the console to flip a state and a fade is checked against the value it ended on, so
    /// neither can work on a leaf the console never reports: `wlive_time` is a command (nothing to flip,
    /// and nothing to read back) and `wlive_marker_set` a 0/1 command of the same kind, and both used to be
    /// accepted — the timeline then aborted with "no answer within 400 ms".
    /// A quiet meter stream must not be read as a dead link: the desk can be answering OSC state while
    /// sending no meters, and tearing the session down told an operator at a live desk that the console
    /// was gone (2026-10-02 — his macro was then refused by the write gate, correctly).
    #[test]
    fn traffic_recently_decides_whether_a_meter_stall_is_a_link_loss() {
        let timeout = Duration::from_millis(3_500);
        let now = Instant::now();
        // Traffic a moment ago: the link is alive, so a silent meter stream keeps the session.
        assert!(traffic_is_recent(Some(now - Duration::from_millis(500)), now, timeout));
        assert!(traffic_is_recent(Some(now - timeout), now, timeout));
        // Nothing for longer than the timeout, or never: the link is gone and the session ends.
        assert!(!traffic_is_recent(
            Some(now - timeout - Duration::from_millis(1)),
            now,
            timeout
        ));
        assert!(!traffic_is_recent(None, now, timeout));
    }

    /// A console write with no live session must be refused, and the refusal must name the state so the
    /// operator knows what to do. Asked for by the owner after Test Action reached a console while the
    /// window said "disconnected" (2026-10-01).
    #[test]
    fn a_console_write_needs_a_live_session() {
        for state in ["", "idle", "stopped", "error", "disconnected", "panic_stop"] {
            let refusal = session_refusal_for_write(state, "testing a step on the console")
                .unwrap_or_else(|| panic!("{state:?} must refuse a console write"));
            assert!(
                refusal.contains("Not connected") && refusal.contains("nothing was sent"),
                "the refusal must say what happened and that nothing was sent: {refusal}"
            );
        }
        for state in ["connecting", "live"] {
            assert!(
                session_refusal_for_write(state, "testing a step on the console").is_none(),
                "{state:?} is a session that is up or coming up, so a write is allowed"
            );
        }
    }

    #[test]
    fn a_command_leaf_takes_a_set_and_not_a_toggle_or_a_fade() {
        let step = |parameter: &str, address: &str, mode: &str, arg_kind: &str| {
            let mut step = default_action_step();
            step.target_category = "wlive".to_string();
            step.target_ids = "1".to_string();
            step.target_parameter = parameter.to_string();
            step.action_address = address.to_string();
            step.action_arg_kind = arg_kind.to_string();
            step.action_value = "1000".to_string();
            step.action_mode = mode.to_string();
            step.fade_start_value = 0.0;
            step.fade_end_value = 1000.0;
            step
        };

        let problems = action_step_problems(
            "Step 1",
            &step("wlive_time", "/cards/wlive/1/$ctl/stime", "fade", "float"),
        );
        assert!(
            problems
                .iter()
                .any(|problem| problem.contains("never reports back")),
            "a fade on a command must be refused: {problems:?}"
        );

        let problems = action_step_problems(
            "Step 1",
            &step("wlive_marker_set", "/cards/wlive/1/$ctl/setmarker", "toggle", "int"),
        );
        assert!(
            problems
                .iter()
                .any(|problem| problem.contains("no state to flip")),
            "a toggle on a command must be refused: {problems:?}"
        );

        // The same key as a plain Set is exactly what the batch is for.
        let problems = action_step_problems(
            "Step 1",
            &step("wlive_time", "/cards/wlive/1/$ctl/stime", "set", "float"),
        );
        assert!(problems.is_empty(), "Set on a command must pass: {problems:?}");
    }

    /// A safes mask is one character per item, and the document gives no clear form: an empty value
    /// and a mask of spaces are both refused with the reason the operator needs, in the step path as
    /// well as in `value_problem` (which the empty-value exemption used to skip for a step).
    #[test]
    fn a_step_on_a_safes_mask_needs_a_mask() {
        let mut step = default_action_step();
        step.target_category = "safes".to_string();
        step.target_ids = "1".to_string();
        step.target_parameter = "safes_ch".to_string();
        step.action_address = "/$ctl/safes/ch".to_string();
        step.action_arg_kind = "string".to_string();
        step.action_mode = "set".to_string();

        for value in ["", "   "] {
            step.action_value = value.to_string();
            let problems = action_step_problems("Step 1", &step);
            assert!(
                problems.iter().any(|problem| problem.contains("needs a value")
                    || problem.contains("character per item")),
                "safes/safes_ch with {value:?} must be refused: {problems:?}"
            );
        }

        step.action_value = "++".to_string();
        assert!(
            action_step_problems("Step 1", &step).is_empty(),
            "a real mask is a real step"
        );

        // The address-only write (`arg_kind = none`) is a different step: it sends the address and
        // no value at all, so the empty-value rule must not touch it.
        step.action_arg_kind = "none".to_string();
        step.action_value = String::new();
        assert!(
            action_step_problems("Step 1", &step).is_empty(),
            "an address-only write carries no value by design"
        );
    }

    /// A write-only command is sent and not read. The catalogue says which keys those are
    /// (`can_trigger = false`), and the read the runtime used to make reported "the console did not
    /// apply /cards/wlive/1/$ctl/control = REC" for a transport command that had landed.
    #[test]
    fn a_write_only_command_is_sent_and_not_read_back() {
        let watchable = test_action_step("/cfg/mon/1/pan", "set", "10");
        assert!(
            expected_value_to_verify(&watchable).is_some(),
            "a reported leaf is verified against the value written"
        );

        let mut command = test_action_step("/cards/wlive/1/$ctl/control", "set", "REC");
        command.write_only = true;
        assert!(
            expected_value_to_verify(&command).is_none(),
            "a command has no state to read back"
        );

        // The flag comes from the catalogue, so the key decides it and not the caller.
        let step = |category: &str, parameter: &str, address: &str, value: &str| {
            let mut step = default_action_step();
            step.target_category = category.to_string();
            step.target_ids = "1".to_string();
            step.target_parameter = parameter.to_string();
            step.action_address = address.to_string();
            step.action_value = value.to_string();
            step
        };
        let mut config = default_show_runner_config();
        config.action_steps = vec![
            step("wlive", "wlive_control", "/cards/wlive/1/$ctl/control", "REC"),
            step("monbus", "monitor_pan", "/cfg/mon/1/pan", "10"),
            step("custom", "raw", "/ch/1/mute", "1"),
        ];
        let action = configured_osc_action_for_config(&config).expect("the three steps compile");
        let flags: Vec<bool> = action.steps.iter().map(|step| step.write_only).collect();
        assert_eq!(
            flags,
            vec![true, false, false],
            "a W-Live command is write-only; a reported leaf and a raw address are not"
        );
    }

    /// The rule the wording list is only data for: the catalogue says what a value *is*, and every
    /// parameter it types as `value_kind == "toggle"` has to reach the editor with both labels.
    ///
    /// The batches that grew the catalogue (solo and talkback, GPIO, the desk switches, the strip
    /// long tail, the transport) each added 0/1 keys, and several of them arrived at the window as a
    /// bare value field because the hand-written list in `parameter_value_metadata` did not grow with
    /// them: an operator was shown "0"/"1" for Solo, Talkback, the talkback assigns, the GPIO state
    /// and the rest. Walking the catalogue fails here instead, so the next batch cannot reopen the
    /// gap by forgetting the list.
    ///
    /// No key is excluded: every catalogue toggle reaches a real leaf whose two positions have to be
    /// named. The two console-reported V2 flags (`meter_v2_gate_led`, `meter_v2_dyn_state`) and the
    /// read-only `gpio_input_state` are not written, but they are still compared by the editor, so
    /// they carry wording too.
    #[test]
    fn every_catalog_toggle_has_on_and_off_wording() {
        let mut missing: Vec<String> = Vec::new();
        for category in target_categories() {
            let mut parameters = wing_core::targets::target_parameters_for_category(category.key);
            for parameter in trigger_parameters_for_category(category.key) {
                if !parameters.iter().any(|listed| listed.key == parameter.key) {
                    parameters.push(parameter);
                }
            }
            for parameter in parameters {
                if parameter.value_kind != "toggle" {
                    continue;
                }
                let dto = parameter_info_to_dto(category.key, &parameter);
                assert_eq!(
                    dto.value_kind, "toggle",
                    "{}/{}: the DTO lost the catalogue's toggle kind",
                    category.key, parameter.key
                );
                let off = dto.off_label.unwrap_or("");
                let on = dto.on_label.unwrap_or("");
                // Both labels, neither empty: "OFF"/"" or "ON"/"ON" tells the operator nothing.
                if off.trim().is_empty() || on.trim().is_empty() || off == on {
                    missing.push(format!(
                        "{}/{} (off: {off:?}, on: {on:?})",
                        category.key, parameter.key
                    ));
                }
            }
        }
        assert!(
            missing.is_empty(),
            "these catalogue toggles reach the editor without ON/OFF wording; add them to `parameter_value_metadata`: {}",
            missing.join(", ")
        );
    }

    #[test]
    fn every_catalog_macro_parameter_resolves() {
        // The only tolerated exceptions are parameters the editor still shows but
        // which cannot resolve to an OSC leaf yet. They must keep failing to
        // resolve: if one starts resolving, this assertion fails and the entry has
        // to leave the list.
        const UNSUPPORTED_CATALOG_PARAMETERS: &[(&str, &str)] = &[
            ("custom", "load_snapshot"),
            ("custom", "load_preset"),
        ];

        for (category, parameter) in UNSUPPORTED_CATALOG_PARAMETERS {
            let target = BasicTargetSpec {
                category: (*category).to_string(),
                ids: "1".to_string(),
                parameter: (*parameter).to_string(),
                send_id: Some(1),
                custom_address: None,
            };
            assert!(
                resolve_basic_addresses(&target).is_empty(),
                "{} / {} is declared unsupported but now resolves; implement it and remove it from the exception list",
                category,
                parameter
            );
        }

        let catalog = target_catalog(None);
        for category in &catalog.categories {
            if let Some(parameters) = catalog.target_parameters_by_category.get(category.key) {
                for parameter in parameters {
                    if UNSUPPORTED_CATALOG_PARAMETERS.contains(&(category.key, parameter.key)) {
                        continue;
                    }
                    let target = BasicTargetSpec {
                        category: category.key.to_string(),
                        ids: "1".to_string(),
                        parameter: parameter.key.to_string(),
                        // Send 2, not 1: a bus sending to itself is refused on purpose (Maillot
                        // footnote 38) and has its own test.
                        send_id: Some(2),
                        custom_address: (category.key == "custom").then(|| "/custom/test".to_string()),
                    };
                    assert!(
                        !resolve_basic_addresses(&target).is_empty(),
                        "dead action selector: {} / {}",
                        category.key,
                        parameter.key
                    );
                }
            }
            if let Some(parameters) = catalog.trigger_parameters_by_category.get(category.key) {
                for parameter in parameters {
                    let target = BasicTargetSpec {
                        category: category.key.to_string(),
                        ids: "1".to_string(),
                        parameter: parameter.key.to_string(),
                        // Send 2: bus 1 to send 1 is refused by Maillot's footnote 38.
                        send_id: Some(2),
                        custom_address: None,
                    };
                    assert!(
                        !resolve_meter_targets(&target).is_empty()
                            || !resolve_basic_addresses(&target).is_empty(),
                        "dead trigger selector: {} / {}",
                        category.key,
                        parameter.key
                    );
                }
            }
        }
    }

    /// A text parameter cannot be compared with `>`: the operator could pick a source, the parameter
    /// "Name" and "rises above -20", and the macro would never fire while the app called it
    /// configured. It has to be refused, naming the parameter and what can be done with it.
    #[test]
    fn a_text_parameter_cannot_be_a_numeric_trigger() {
        let mut config = default_show_runner_config();
        config.trigger_category = "preamp_aes50c".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "name".to_string();
        config.trigger_operator = ">".to_string();
        config.trigger_threshold = -20.0;

        let result = preflight_config(config);

        assert!(
            !result.ok,
            "a trigger on a text parameter with > must be refused, not silently never fire"
        );
        assert!(
            result.messages.iter().any(|message| message.contains("Name")),
            "the reason must name the parameter: {:?}",
            result.messages
        );
    }

    /// The same parameter with `==` and a name is a real trigger ("when the channel is called X"),
    /// so the rule is about the comparator, not about banning the parameter.
    #[test]
    fn a_text_parameter_can_be_compared_for_equality() {
        let mut config = default_show_runner_config();
        config.trigger_category = "preamp_aes50c".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "name".to_string();
        config.trigger_operator = "==".to_string();
        config.trigger_value = Some("VOX 1".to_string());

        let result = preflight_config(config);

        assert!(result.ok, "comparing a name for equality is valid: {:?}", result.messages);
    }

    /// The compile path is the only gate a hand-edited show file cannot skip, so it must refuse what
    /// the Arm button refuses.
    #[test]
    fn the_compile_path_refuses_a_text_trigger_compared_with_greater_than() {
        let mut config = default_show_runner_config();
        config.trigger_category = "preamp_aes50c".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "name".to_string();
        config.trigger_operator = ">".to_string();
        config.trigger_threshold = -20.0;

        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a name compared with > must not compile");
        assert!(error.contains("Name"), "{error}");
        assert!(error.contains("text"), "{error}");
    }

    /// And the equality form does compile, with the text as the value the console compares.
    #[test]
    fn the_compile_path_accepts_a_name_compared_for_equality() {
        let mut config = default_show_runner_config();
        config.trigger_category = "preamp_aes50c".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "name".to_string();
        config.trigger_operator = "==".to_string();
        config.trigger_value = Some("VOX 1".to_string());

        let macro_config =
            configured_macro_from_config("macro-1".to_string(), config).expect("compiles");
        assert_eq!(
            macro_config.subscription.osc_triggers[0].value, "VOX 1",
            "the comparison value must be the text the operator typed"
        );
    }

    /// A level meter is a moving stream: only a crossing means anything, and the compiler must not
    /// turn `==` into one behind the operator's back.
    #[test]
    fn a_meter_trigger_with_equality_is_refused_instead_of_becoming_a_rising_crossing() {
        let mut config = default_show_runner_config();
        config.trigger_category = "ch".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "meter".to_string();
        config.trigger_operator = "==".to_string();
        config.trigger_threshold = -20.0;

        assert!(
            configured_macro_from_config("macro-1".to_string(), config).is_err(),
            "a level meter cannot be compared with equals"
        );
    }

    /// The V2 flags are on/off, so ON/OFF is the comparison and the crossing sits at 0.5; a dB
    /// threshold on a 0/1 stream could never be crossed (the audit's B3).
    #[test]
    fn a_v2_flag_meter_is_compared_with_on_off() {
        let target = BasicTargetSpec {
            category: "ch".to_string(),
            ids: "1".to_string(),
            parameter: "meter_v2_gate_led".to_string(),
            send_id: None,
            custom_address: None,
        };
        let subscription = trigger_subscription_for_target(
            &target,
            -18.0,
            "1",
            "==",
            "on",
            MeterTriggerPolicy::fast_transient(),
        )
        .expect("the flag compiles with ON");
        let trigger = &subscription.triggers[0];
        assert_eq!(trigger.threshold, 0.5, "the crossing of a 0/1 stream is a half");
        assert_eq!(trigger.direction, TriggerDirection::Rising);
    }

    #[test]
    fn a_fade_on_a_toggle_is_refused() {
        let mut config = default_show_runner_config();
        config.action_steps[0].action_mode = "fade".to_string();
        config.action_steps[0].target_category = "ch".to_string();
        config.action_steps[0].target_ids = "1".to_string();
        config.action_steps[0].target_parameter = "mute".to_string();

        let result = preflight_config(config);
        assert!(!result.ok, "a fade writes numbers: a mute cannot be ramped");
        assert!(
            result.messages.iter().any(|message| message.contains("continuous")),
            "{:?}",
            result.messages
        );
    }

    #[test]
    fn a_send_outside_the_documented_range_is_refused() {
        let mut config = default_show_runner_config();
        config.action_steps[0].target_category = "ch".to_string();
        config.action_steps[0].target_ids = "1".to_string();
        config.action_steps[0].target_parameter = "send_level".to_string();
        config.action_steps[0].send_id = Some(17);

        let result = preflight_config(config);
        assert!(!result.ok, "the console has buses 1 to 16 (Maillot 2159)");
        // The reason used to say "the console has sends 1 to 16" whatever the parameter addressed.
        // It now names the destination the index counts, which is the only way the operator can tell
        // a bus 17 from a matrix 9.
        assert!(
            result
                .messages
                .iter()
                .any(|message| message
                    == "Step 1: send 17 does not exist; the Bus has 16 destinations."),
            "{:?}",
            result.messages
        );
    }

    #[test]
    fn a_bus_sending_to_itself_is_refused_with_the_reason() {
        let mut config = default_show_runner_config();
        config.action_steps[0].target_category = "bus".to_string();
        config.action_steps[0].target_ids = "1".to_string();
        config.action_steps[0].target_parameter = "send_on".to_string();
        config.action_steps[0].send_id = Some(1);

        let result = preflight_config(config);
        assert!(!result.ok);
        assert!(
            result.messages.iter().any(|message| message.contains("itself")),
            "{:?}",
            result.messages
        );

        // A list that contains the destination is refused too: the resolver drops that one address,
        // so the step would write the other buses and quietly not the one the operator listed.
        let mut config = default_show_runner_config();
        config.action_steps[0].target_category = "bus".to_string();
        config.action_steps[0].target_ids = "2,3".to_string();
        config.action_steps[0].target_parameter = "send_on".to_string();
        config.action_steps[0].send_id = Some(2);

        let result = preflight_config(config);
        assert!(!result.ok);
        assert!(
            result
                .messages
                .iter()
                .any(|message| message
                    == "Step 1: bus 2 cannot send to itself (Maillot footnote 38)."),
            "{:?}",
            result.messages
        );
    }

    /// Every destination has its own size — buses 16 (`/ch/1/send/1`, Maillot 2159), matrices 8
    /// (`/ch/1/send/MX<x>`, 2168), mains 4 (`/ch/1/main/1`, 2153) — and the reason names it. The old
    /// check was a hard-coded `1..=16`, so "send Matrix 9" armed and the console ignored the write.
    #[test]
    fn a_send_index_is_refused_above_its_destination() {
        let messages_for = |category: &str, parameter: &str, send_id: u8| -> Vec<String> {
            let mut config = default_show_runner_config();
            config.action_steps[0].target_category = category.to_string();
            config.action_steps[0].target_ids = "1".to_string();
            config.action_steps[0].target_parameter = parameter.to_string();
            config.action_steps[0].send_id = Some(send_id);
            preflight_config(config).messages
        };

        let matrix = messages_for("ch", "send_matrix_level", 9);
        assert!(
            matrix
                .iter()
                .any(|message| message
                    == "Step 1: send 9 does not exist; the Matrix has 8 destinations."),
            "{matrix:?}"
        );

        let main = messages_for("ch", "send_main_level", 5);
        assert!(
            main.iter()
                .any(|message| message
                    == "Step 1: send 5 does not exist; the Main has 4 destinations."),
            "{main:?}"
        );

        // 16 is the last bus and has to stay accepted: the bound moved, it did not tighten.
        let bus = messages_for("ch", "send_level", 16);
        assert!(
            !bus.iter().any(|message| message.contains("does not exist")),
            "{bus:?}"
        );
    }

    /// A send without a destination used to become send 1 in silence — on a bus that is the
    /// self-send footnote 38 says the console ignores, and on any other family the operator could
    /// not see which destination the macro wrote. Every send now fails closed, in the trigger, in
    /// the IF gate and in the step list, with a reason that names the range to fill in.
    #[test]
    fn a_send_without_a_destination_is_refused() {
        let mut config = default_show_runner_config();
        config.trigger_category = "bus".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "send_on".to_string();
        config.trigger_operator = "==".to_string();
        config.trigger_value = Some("1".to_string());
        config.send_id = None;

        let result = preflight_config(config.clone());
        assert!(!result.ok);
        assert!(
            result.messages.iter().any(|message| message
                == "Trigger: choose the bus this send feeds (1…16); without one the step has no address."),
            "{:?}",
            result.messages
        );
        // Nothing is built either: the compile path is the gate a hand-edited show file cannot skip.
        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a bus send without a destination must not compile");
        assert!(error.contains("without one the step has no address"), "{error}");

        // The same rule on a channel: no destination, no address — the silent default is gone.
        let mut channel = default_show_runner_config();
        channel.trigger_category = "ch".to_string();
        channel.trigger_ids = "1".to_string();
        channel.trigger_parameter = "send_level".to_string();
        channel.send_id = None;
        let result = preflight_config(channel);
        assert!(!result.ok, "a channel send with no destination must be refused too");
        assert!(
            result.messages.iter().any(|message| message
                .starts_with("Trigger: choose the bus this send feeds")),
            "{:?}",
            result.messages
        );

        let mut gated = default_show_runner_config();
        gated.conditions.push(ShowConditionDto {
            label: "bus send live".to_string(),
            target_category: "bus".to_string(),
            target_ids: "2".to_string(),
            target_parameter: "send_on".to_string(),
            send_id: None,
            target_model: None,
            operator: "==".to_string(),
            value: "1".to_string(),
            enabled: true,
        });
        let result = preflight_config(gated);
        assert!(!result.ok);
        assert!(
            result.messages.iter().any(|message| message
                .starts_with("Gate 1: choose the bus this send feeds")),
            "{:?}",
            result.messages
        );
    }

    /// The index is not only bounded and refused: it travels into the address the runtime watches, for
    /// the trigger and for the IF gate alike. Without this the destination could be validated and then
    /// dropped on the way to the resolver, which is how a bus trigger watched bus 1.
    #[test]
    fn a_send_destination_travels_into_the_watched_address() {
        let mut config = default_show_runner_config();
        config.trigger_category = "ch".to_string();
        config.trigger_ids = "2".to_string();
        config.trigger_parameter = "send_matrix_on".to_string();
        config.trigger_operator = "==".to_string();
        config.trigger_value = Some("1".to_string());
        config.send_id = Some(3);
        config.conditions.push(ShowConditionDto {
            label: "main send live".to_string(),
            target_category: "bus".to_string(),
            target_ids: "4".to_string(),
            target_parameter: "send_main_pre".to_string(),
            send_id: Some(2),
            target_model: None,
            operator: "==".to_string(),
            value: "1".to_string(),
            enabled: true,
        });

        let macro_config =
            configured_macro_from_config("macro-1".to_string(), config).expect("compiles");
        assert_eq!(
            macro_config.subscription.osc_triggers[0].addresses,
            vec!["/ch/2/send/MX3/on".to_string()],
            "the trigger watches the matrix 3 send of channel 2, not matrix 1"
        );
        assert_eq!(
            macro_config.conditions.rows[0].osc_addresses,
            vec!["/bus/4/main/2/pre".to_string()],
            "the gate watches the main 2 send of bus 4"
        );

        // A send tap is a choice: it compares with `==` and carries its word (`PRE`, Maillot 2163),
        // never a numeric threshold, and its destination travels the same way.
        let mut config = default_show_runner_config();
        config.trigger_category = "ch".to_string();
        config.trigger_ids = "2".to_string();
        config.trigger_parameter = "send_mode".to_string();
        config.trigger_operator = "==".to_string();
        config.trigger_value = Some("PRE".to_string());
        config.send_id = Some(4);
        let macro_config =
            configured_macro_from_config("macro-2".to_string(), config).expect("compiles");
        let tap = &macro_config.subscription.osc_triggers[0];
        assert_eq!(tap.addresses, vec!["/ch/2/send/4/mode".to_string()]);
        assert_eq!(
            tap.value, "PRE",
            "a tap point is compared as text, not as a threshold"
        );
    }

    /// An index outside its destination is refused by the compile path too, not only by the
    /// preflight button: an imported or hand-edited macro must not reach the console with a send
    /// that does not exist.
    #[test]
    fn an_out_of_range_send_index_never_reaches_the_console() {
        let mut config = default_show_runner_config();
        config.trigger_category = "ch".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "send_matrix_on".to_string();
        config.trigger_operator = "==".to_string();
        config.trigger_value = Some("1".to_string());
        config.send_id = Some(9);

        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("matrix 9 does not exist");
        assert!(
            error.contains("send 9 does not exist; the Matrix has 8 destinations."),
            "{error}"
        );

        let mut config = default_show_runner_config();
        config.action_steps[0].target_category = "ch".to_string();
        config.action_steps[0].target_parameter = "send_main_level".to_string();
        config.action_steps[0].send_id = Some(5);

        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("main 5 does not exist");
        assert!(
            error.contains("send 5 does not exist; the Main has 4 destinations."),
            "{error}"
        );
    }

    /// The editor bounds its destination selector with the parameter row, so the row has to carry
    /// the bound and the name of what the index counts — under the exact names it reads.
    #[test]
    fn the_editor_learns_the_destination_of_a_send() {
        let catalog = target_catalog(None);
        let target_of = |category: &str, key: &str| {
            catalog
                .target_parameters_by_category
                .get(category)
                .unwrap_or_else(|| panic!("{category} target parameters"))
                .iter()
                .find(|parameter| parameter.key == key)
                .unwrap_or_else(|| panic!("{category} / {key} is offered"))
        };

        let bus = target_of("ch", "send_level");
        assert_eq!(bus.send_index_label, Some("Bus"));
        assert_eq!(bus.send_index_max, Some(16));

        let matrix = target_of("ch", "send_matrix_level");
        assert_eq!(matrix.send_index_label, Some("Matrix"));
        assert_eq!(matrix.send_index_max, Some(8));

        let main = target_of("ch", "send_main_level");
        assert_eq!(main.send_index_label, Some("Main"));
        assert_eq!(main.send_index_max, Some(4));

        // What the editor actually reads: the serialised camelCase names.
        let json = serde_json::to_value(bus).expect("the row serialises");
        assert_eq!(json["sendIndexLabel"], "Bus");
        assert_eq!(json["sendIndexMax"], 16);

        // A parameter that takes no destination index must say so, or the editor draws a field that
        // addresses nothing.
        let fader = target_of("ch", "fader");
        assert_eq!(fader.send_index_max, None);
        assert_eq!(fader.send_index_label, None);
        let json = serde_json::to_value(fader).expect("the row serialises");
        assert!(json.get("sendIndexMax").is_none(), "{json}");
        assert!(json.get("sendIndexLabel").is_none(), "{json}");
    }

    /// `/fx/<slot>/mdl` is a closed list that depends on the slot: slots 1…8 load the full list
    /// (Maillot 2896-2919) and 9…16 the reduced one (2921-2934), so a premium model in a reduced
    /// slot is a name the console keeps without a word.
    #[test]
    fn an_fx_model_belongs_to_its_slot() {
        // The catalogue tells the editor this is a closed list of names, not free text.
        let catalog = target_catalog(None);
        let dto = catalog
            .target_parameters_by_category
            .get("fx")
            .expect("fx target parameters")
            .iter()
            .find(|parameter| parameter.key == "fx_model")
            .expect("the FX model is offered");
        assert_eq!(dto.value_kind, "enum");
        assert_eq!(dto.operators, ["==", "!="], "a model is compared, never ordered");
        assert!(dto.options.iter().any(|option| option.value == "HALL"));

        let step_config = |slot: &str, value: &str| {
            let mut config = default_show_runner_config();
            config.action_steps[0].target_category = "fx".to_string();
            config.action_steps[0].target_ids = slot.to_string();
            config.action_steps[0].target_parameter = "fx_model".to_string();
            config.action_steps[0].action_value = value.to_string();
            config.action_steps[0].action_arg_kind = "string".to_string();
            // The address the selector resolves to, which is what the editor stores: the closed-list
            // check belongs to the parameter the selector names, and it only governs that address
            // (`step_selector_owns_address`), exactly as the value check does.
            config.action_steps[0].action_address = format!("/fx/{slot}/mdl");
            config
        };

        // HALL is a slot 1…8 model and cannot be loaded in slot 12.
        let result = preflight_config(step_config("12", "HALL"));
        assert!(!result.ok, "{:?}", result.messages);
        assert!(
            result.messages.iter().any(|message| message
                == "Step 1: HALL cannot be loaded in FX slot 12; FX slots 9…16 load effects only (Maillot 2921-2934)."),
            "{:?}",
            result.messages
        );

        // The same model in slot 1 is what the slot is for.
        let result = preflight_config(step_config("1", "HALL"));
        assert!(result.ok, "{:?}", result.messages);

        // A name outside the documented list names the list the console takes.
        let result = preflight_config(step_config("1", "DELREV"));
        assert!(!result.ok);
        assert!(
            result.messages.iter().any(|message| message
                .contains("FX Model must be one of")
                && message.contains("DEQ3")),
            "{:?}",
            result.messages
        );

        // The IF-gate path takes its kind and its list from the catalogue as well: it used to call
        // `fx_model` free text, so a misspelt model was watched for ever instead of being refused.
        let condition = |value: &str, slot: &str| ShowConditionDto {
            label: "fx model gate".to_string(),
            target_category: "fx".to_string(),
            target_ids: slot.to_string(),
            target_parameter: "fx_model".to_string(),
            send_id: None,
            target_model: None,
            operator: "==".to_string(),
            value: value.to_string(),
            enabled: true,
        };
        let configured = configured_conditions(None, Some(vec![condition("HALL", "1")]), 2000)
            .expect("a slot 1 model is a valid comparison");
        assert_eq!(configured.rows[0].value, "HALL");
        let error = configured_conditions(None, Some(vec![condition("DELREV", "1")]), 2000)
            .err()
            .expect("a name outside the documented list cannot be watched");
        assert!(error.contains("documented values"), "{error}");

        // …and the slot rule reaches the gate too, since the address alone cannot say it.
        let mut gated = default_show_runner_config();
        gated.conditions.push(condition("HALL", "12"));
        let result = preflight_config(gated);
        assert!(
            result.messages.iter().any(|message| message
                == "Gate 1: HALL cannot be loaded in FX slot 12; FX slots 9…16 load effects only (Maillot 2921-2934)."),
            "{:?}",
            result.messages
        );
    }

    /// A macro whose only step writes a model-scoped parameter, with the model the editor read for
    /// that strip. The address is the one the selector resolves to, because that is what the editor
    /// stores and what the console is written.
    fn model_parameter_step_config(
        category: &str,
        parameter: &str,
        model: Option<&str>,
    ) -> ShowRunnerConfigDto {
        let mut config = default_show_runner_config();
        let step = &mut config.action_steps[0];
        step.target_category = category.to_string();
        step.target_ids = "1".to_string();
        step.target_parameter = parameter.to_string();
        step.target_model = model.map(str::to_string);
        step.send_id = Some(default_send_id());
        let target = BasicTargetSpec {
            category: step.target_category.clone(),
            ids: step.target_ids.clone(),
            parameter: step.target_parameter.clone(),
            send_id: step.send_id,
            custom_address: None,
        };
        step.action_address = resolve_basic_addresses(&target)
            .into_iter()
            .next()
            .unwrap_or_default();
        config
    }

    /// The defect the macro audit opened with: a step on `dyn:thr` while the strip's compressor
    /// runs WARM, which has no `thr` at all. `/ch/1/dyn/thr` is a well formed address, the console
    /// ignores it without a word, and the macro reported success. The model the editor read travels
    /// with the step and the name is refused before a packet is built (Maillot 3.1.0 appendix).
    #[test]
    fn a_step_on_a_parameter_the_strips_model_does_not_have_is_refused() {
        let config = model_parameter_step_config("ch", "dyn:thr", Some("WARM"));

        let result = preflight_config(config.clone());
        assert!(
            !result.ok,
            "WARM has no \"thr\": the write would be ignored in silence, so it cannot arm: {:?}",
            result.messages
        );
        assert!(
            result.messages.iter().any(|message| message.starts_with("Step 1: ")
                && message.contains("WARM")
                && message.contains("dyn")
                && message.contains("\"thr\"")),
            "the reason must name the model, the section and the name: {:?}",
            result.messages
        );
        let warm_names = wing_core::targets::model_parameter_names("WARM");
        assert!(
            !warm_names.is_empty()
                && result.messages.iter().any(|message| warm_names
                    .iter()
                    .any(|name| message.contains(name))),
            "the reason must list names WARM actually has ({warm_names:?}): {:?}",
            result.messages
        );

        // The compile path is the gate a hand-edited show file cannot skip.
        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a step on a name the strip's model lacks must not compile");
        assert!(error.contains("WARM"), "{error}");
    }

    /// The same step on a model that does carry the name: COMP has `thr`, so nothing is refused.
    #[test]
    fn a_step_on_a_parameter_the_strips_model_has_is_accepted() {
        let config = model_parameter_step_config("ch", "dyn:thr", Some("COMP"));

        let result = preflight_config(config.clone());
        assert!(
            result.ok,
            "COMP carries \"thr\", so the step is the one the operator meant: {:?}",
            result.messages
        );
        assert!(
            configured_macro_from_config("macro-1".to_string(), config).is_ok(),
            "and it compiles"
        );
    }

    /// An FX slot's parameters are steps the app can write, gated by the model the slot runs: the
    /// editor reads `/fx/<slot>/mdl` (Maillot 2896-2934) and the step carries the answer, exactly as a
    /// strip's step carries its gate/dyn/EQ model. The address is `/fx/<slot>/<name>`
    /// (2940-2942: "up to 4048 parameters that depend on the selected model").
    #[test]
    fn a_step_on_an_fx_parameter_is_gated_by_the_slots_model() {
        // `flc` is the flanger's feedback low cut (7760) and the chorus has no such row, so the very
        // same address means two different things on two models.
        let config = model_parameter_step_config("fx", "fx:flc", Some("FLANGER"));
        assert_eq!(config.action_steps[0].action_address, "/fx/1/flc");
        let result = preflight_config(config.clone());
        assert!(result.ok, "{:?}", result.messages);
        assert!(configured_macro_from_config("macro-1".to_string(), config).is_ok());

        let config = model_parameter_step_config("fx", "fx:flc", Some("CHORUS"));
        assert_eq!(
            config.action_steps[0].action_address, "/fx/1/flc",
            "the address is well formed either way, which is why the model decides"
        );
        let result = preflight_config(config.clone());
        assert!(!result.ok, "{:?}", result.messages);
        assert!(
            result.messages.iter().any(|message| message.starts_with("Step 1: ")
                && message.contains("CHORUS")
                && message.contains("\"flc\"")),
            "the reason must name the model the slot runs and the name it lacks: {:?}",
            result.messages
        );
        assert!(
            configured_macro_from_config("macro-1".to_string(), config).is_err(),
            "the compile path refuses it too: a hand-edited show cannot skip the check"
        );

        // The model travels under the console's own spelling: `V-IMG` is the appendix's `V_IMG` table
        // (2916), and `mode` is one of its five rows.
        let config = model_parameter_step_config("fx", "fx:mode", Some("V-IMG"));
        assert!(preflight_config(config).ok, "the console's spelling resolves");
        // The same name on the model that does not carry it is refused, so the check is not a
        // formality that passes because the table resolved.
        let config = model_parameter_step_config("fx", "fx:mode", Some("FLANGER"));
        assert!(!preflight_config(config).ok);
    }

    /// An FX parameter whose step arrived without the slot's model keeps the "not checked" note, as a
    /// strip parameter does: nothing is refused — an older file must keep working — but the operator is
    /// told which leaf decides it, and for an effect that leaf is `/fx/<slot>/mdl`.
    #[test]
    fn an_fx_parameter_without_its_model_keeps_the_note() {
        let mut config = model_parameter_step_config("fx", "fx:lc", None);
        config.action_steps[0].action_arg_kind = "float".to_string();
        config.action_steps[0].action_value = "400".to_string();

        let result = preflight_config(config.clone());
        assert!(
            result.ok,
            "a macro saved before the model travelled must keep working: {:?}",
            result.messages
        );
        assert!(
            result.messages.iter().any(|message| message.starts_with("Step 1: ")
                && message.contains("was not checked")
                && message.contains("/fx/<slot>/mdl")),
            "the note must say which model was not checked and where to read it: {:?}",
            result.messages
        );
        assert!(configured_macro_from_config("macro-1".to_string(), config).is_ok());
    }

    /// The window is told how to reach an effect model's parameters: `/fx/<slot>/mdl` reports a name
    /// that three appendix tables spell differently (`ROOM`, `DEL/REV`, `V-IMG` at 2897, 2901, 2916),
    /// and the catalogue maps the console's spelling onto the `pluginModels` entry that documents it,
    /// so a picker that has just read the slot needs one lookup and no second copy of the tables.
    #[test]
    fn the_catalog_maps_each_fx_model_onto_its_appendix_table() {
        let catalog = target_catalog(None);
        assert_eq!(
            catalog.fx_model_tables.len(),
            wing_core::targets::fx_models().len(),
            "one entry per model the console offers, and no appendix-only spelling"
        );
        for (reported, table) in [
            ("ROOM", "R-OOM"),
            ("DEL/REV", "DELREV"),
            ("V-IMG", "V_IMG"),
            ("CHORUS", "CHORUS"),
            ("FLANGER", "FLANGER"),
        ] {
            let entry = catalog
                .fx_model_tables
                .iter()
                .find(|entry| entry.model == reported)
                .unwrap_or_else(|| panic!("/fx/<slot>/mdl offers {reported}"));
            assert_eq!(entry.table, table, "{reported} documents the {table} table");
            let model = catalog
                .plugin_models
                .iter()
                .find(|model| model.model == table)
                .unwrap_or_else(|| panic!("{table} must be published for the picker"));
            assert!(!model.parameters.is_empty(), "{table} has no parameters");
        }
        // The picker's two models are not each other's: the flanger offers `flc`, the chorus does not.
        let parameters = |table: &str| {
            catalog
                .plugin_models
                .iter()
                .find(|model| model.model == table)
                .map(|model| model.parameters.iter().map(|p| p.key).collect::<Vec<_>>())
                .unwrap_or_default()
        };
        assert!(parameters("FLANGER").contains(&"flc"));
        assert!(!parameters("CHORUS").contains(&"flc"));
        assert!(parameters("CHORUS").contains(&"sprd"));
        // A picker's rows carry the comparators as well, so an FX parameter can be wired as a watch
        // without the window keeping a second copy of the kind table: `lc` is a frequency
        // (`logf [20, 400, 51] Hz, LC`, 7743) and `cab` a switch (`int [0, 1] cab sim`, 7215).
        let parameter = |table: &str, key: &str| {
            catalog
                .plugin_models
                .iter()
                .find(|model| model.model == table)
                .and_then(|model| model.parameters.iter().find(|row| row.key == key))
                .unwrap_or_else(|| panic!("{table} must publish {key}"))
        };
        assert_eq!(parameter("FLANGER", "lc").value_kind, "hz");
        assert_eq!(parameter("FLANGER", "lc").operators, ["<", ">", "==", "!="]);
        assert_eq!(parameter("RACKAMP", "cab").value_kind, "toggle");
        assert_eq!(parameter("RACKAMP", "cab").operators, ["==", "!="]);
        // The `fx:<name>` key a picker builds from these rows is the one the resolver accepts.
        let target = BasicTargetSpec {
            category: "fx".to_string(),
            ids: "1".to_string(),
            parameter: "fx:flc".to_string(),
            send_id: None,
            custom_address: None,
        };
        assert_eq!(resolve_basic_addresses(&target), vec!["/fx/1/flc"]);
    }

    /// Without a model there is nothing to check the name against — an older file, an import and a
    /// hand-edited show keep working — but the operator is told the model was not checked instead of
    /// being left to trust a write that may have been ignored.
    #[test]
    fn a_model_parameter_without_the_strips_model_is_accepted_with_a_note() {
        let config = model_parameter_step_config("ch", "dyn:thr", None);

        let result = preflight_config(config.clone());
        assert!(
            result.ok,
            "a macro saved before the model travelled must keep working: {:?}",
            result.messages
        );
        assert!(
            result.messages.iter().any(|message| message.starts_with("Step 1: ")
                && message.contains("was not checked")),
            "the note must say the model was not checked: {:?}",
            result.messages
        );
        assert!(
            configured_macro_from_config("macro-1".to_string(), config).is_ok(),
            "and it still compiles"
        );
    }

    /// An unknown model string is refused rather than accepted in silence: "XYZ" cannot be said to
    /// have the name or not to have it, so nothing is written.
    #[test]
    fn an_undocumented_model_is_refused() {
        let config = model_parameter_step_config("ch", "dyn:thr", Some("XYZ"));

        let result = preflight_config(config.clone());
        assert!(!result.ok, "{:?}", result.messages);
        assert!(
            result.messages.iter().any(|message| message.starts_with("Step 1: ")
                && message.contains("XYZ")
                && message.contains("documented")),
            "{:?}",
            result.messages
        );

        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("an undocumented model must not compile");
        assert!(error.contains("XYZ"), "{error}");
    }

    /// The trigger carries the model of its own strip, and the IF gate carries its own: "when the
    /// gate threshold rises" must not be armed against a parameter the strip does not have.
    #[test]
    fn the_trigger_and_the_if_gate_are_checked_against_the_strips_model() {
        let mut config = default_show_runner_config();
        config.trigger_category = "ch".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "dyn:thr".to_string();
        config.target_model = Some("WARM".to_string());
        config.trigger_operator = ">".to_string();
        config.trigger_value = Some("-6".to_string());

        let result = preflight_config(config.clone());
        assert!(!result.ok, "{:?}", result.messages);
        assert!(
            result.messages.iter().any(|message| message.starts_with("Trigger: ")
                && message.contains("WARM")
                && message.contains("\"thr\"")),
            "the trigger must be refused with the model named: {:?}",
            result.messages
        );
        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a trigger on a name the strip's model lacks must not compile");
        assert!(error.contains("WARM"), "{error}");

        // A gate on a `DEQ2` strip: the DEQ2 gate has `1-thr`/`2-thr` and no `thr`.
        let mut config = default_show_runner_config();
        config.conditions.push(ShowConditionDto {
            label: "gate threshold".to_string(),
            target_category: "ch".to_string(),
            target_ids: "1".to_string(),
            target_parameter: "gate:thr".to_string(),
            send_id: None,
            target_model: Some("DEQ2".to_string()),
            operator: ">".to_string(),
            value: "-20".to_string(),
            enabled: true,
        });

        let result = preflight_config(config.clone());
        assert!(!result.ok, "{:?}", result.messages);
        assert!(
            result.messages.iter().any(|message| message.starts_with("Gate 1: ")
                && message.contains("DEQ2")
                && message.contains("1-thr")),
            "the gate must be refused with the model and a name it has: {:?}",
            result.messages
        );
        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a gate on a name the strip's model lacks must not compile");
        assert!(error.contains("DEQ2"), "{error}");

        // …and on the model that does have the name, the model check has nothing to say. The gate is
        // still refused, and by the older rule: a `section:name` parameter is not a catalogue row the
        // console reports, so it can never be *watched* — the editor only offers model parameters as
        // write targets. Failing closed there is the behaviour that already existed; what this test
        // pins is that the model reason is not among the reasons when the model has the name.
        let mut config = default_show_runner_config();
        config.conditions.push(ShowConditionDto {
            label: "gate threshold".to_string(),
            target_category: "ch".to_string(),
            target_ids: "1".to_string(),
            target_parameter: "gate:thr".to_string(),
            send_id: None,
            target_model: Some("GATE".to_string()),
            operator: ">".to_string(),
            value: "-20".to_string(),
            enabled: true,
        });
        let result = preflight_config(config);
        assert!(
            !result.messages.iter().any(|message| message.starts_with("Gate 1: ")
                && message.contains("GATE")
                && message.contains("has no")),
            "GATE carries \"thr\": the model must not be blamed: {:?}",
            result.messages
        );
    }

    /// The other spelling of the same leaf is checked too: the plain catalogue keys the editor offers
    /// (`gate_thr` → `/gate/thr`, `comp_thr` → `/dyn/thr`, `dyn_drv` → `/dyn/drv`, `eq_1_gain` →
    /// `/eq/1g`, `eq_low_gain` → `/eq/lg`) reach exactly the address the `section:name` targets do, so
    /// a macro on one of them against a strip whose slot runs a model without that name used to
    /// compile and could never fire — the failure the model check exists to stop (macro audit of
    /// 2026-09-24, open item 1).
    #[test]
    fn a_catalogue_key_is_checked_against_the_strips_model() {
        // The address is the one the selector resolves to, and the value is inside the range the
        // catalogue documents for that key, so the model name is the only reason left to refuse.
        let step_config = |parameter: &str, model: Option<&str>, value: &str| {
            let mut config = model_parameter_step_config("ch", parameter, model);
            config.action_steps[0].action_arg_kind = "float".to_string();
            config.action_steps[0].action_value = value.to_string();
            config
        };

        for (parameter, value, model) in [
            // A DEQ2 gate has `1-thr`/`2-thr` and no `thr`; a WARM compressor has no `thr` at all
            // and no `ratio`; COMP has no `drv`; the SOUL EQ has no `1g`.
            ("gate_thr", "-40", "DEQ2"),
            ("comp_thr", "-20", "WARM"),
            ("comp_ratio", "2.0", "WARM"),
            ("dyn_drv", "50", "COMP"),
            ("eq_1_gain", "3", "SOUL"),
            ("eq_low_gain", "-3", "PULSAR"),
        ] {
            let config = step_config(parameter, Some(model), value);
            let result = preflight_config(config.clone());
            assert!(
                !result.ok,
                "{parameter} on {model}: the console would ignore the write in silence: {:?}",
                result.messages
            );
            assert!(
                result.messages.iter().any(|message| message.starts_with("Step 1: ")
                    && message.contains(model)
                    && message.contains("has no")),
                "{parameter} on {model}: the reason must name the model: {:?}",
                result.messages
            );
            let error = configured_macro_from_config("macro-1".to_string(), config)
                .err()
                .unwrap_or_else(|| panic!("{parameter} on {model} must not compile"));
            assert!(error.contains(model), "{error}");
        }

        // …and the same keys on a model that does carry the name are accepted, so the check cannot
        // pass by refusing every catalogue key.
        for (parameter, value, model) in [
            ("gate_thr", "-40", "GATE"),
            ("comp_thr", "-20", "COMP"),
            ("dyn_drv", "50", "WARM"),
            ("eq_1_gain", "3", "STD"),
            ("eq_low_gain", "-3", "STD"),
        ] {
            let config = step_config(parameter, Some(model), value);
            let result = preflight_config(config.clone());
            assert!(
                result.ok,
                "{parameter} on {model}: it carries the name, so nothing may be refused: {:?}",
                result.messages
            );
            assert!(
                configured_macro_from_config("macro-1".to_string(), config).is_ok(),
                "{parameter} on {model} must compile"
            );
        }

        // The one appendix row the extraction mangled: STD's band-6 Q is printed `7q` but the console
        // leaf is `/eq/6q` (bus 2434, main 2605, matrix 2775). Bands 5 and 6 exist on bus, main and
        // matrix only, and the table teaches the alias, so the plain key is not refused on the model
        // that really has it.
        let mut config = model_parameter_step_config("bus", "eq_6_q", Some("STD"));
        config.action_steps[0].action_arg_kind = "float".to_string();
        config.action_steps[0].action_value = "1.0".to_string();
        assert_eq!(config.action_steps[0].action_address, "/bus/1/eq/6q");
        let result = preflight_config(config.clone());
        assert!(
            result.ok,
            "STD's `/eq/6q` must not be blamed for the appendix printing `7q`: {:?}",
            result.messages
        );
        assert!(configured_macro_from_config("macro-1".to_string(), config).is_ok());

        // A raw custom address is not judged by a leftover catalogue key, for the model rule exactly
        // as for the value rules: the key names the leaf the selector resolves to, and this step
        // writes somewhere else. The model would be blamed for a write it has nothing to do with.
        let mut config = model_parameter_step_config("ch", "gate_thr", Some("DEQ2"));
        config.action_steps[0].action_address = "/custom/anything".to_string();
        let problems = action_steps_problems(&sendable_action_steps(&config));
        assert!(
            !problems.iter().any(|problem| problem.contains("DEQ2")),
            "a custom address is not the model's leaf: {problems:?}"
        );
    }

    /// The trigger is where the defect was found, and it is checked the same way: "when the gate
    /// threshold rises" written as the catalogue key cannot arm against a DEQ2 gate, because that
    /// strip has no `/gate/thr` and the comparison would never be reported at all.
    #[test]
    fn a_catalogue_trigger_is_checked_against_the_strips_model() {
        let mut config = default_show_runner_config();
        config.trigger_category = "ch".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "gate_thr".to_string();
        config.trigger_operator = ">".to_string();
        config.trigger_threshold = -40.0;
        config.target_model = Some("DEQ2".to_string());

        let result = preflight_config(config.clone());
        assert!(!result.ok, "{:?}", result.messages);
        assert!(
            result.messages.iter().any(|message| message.starts_with("Trigger: ")
                && message.contains("DEQ2")
                && message.contains("\"thr\"")),
            "the trigger must be refused with the model named: {:?}",
            result.messages
        );
        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a trigger on a name the strip's model lacks must not compile");
        assert!(error.contains("DEQ2"), "{error}");

        // On the model that has it, nothing is said about the model.
        let mut config = default_show_runner_config();
        config.trigger_category = "ch".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "gate_thr".to_string();
        config.trigger_operator = ">".to_string();
        config.trigger_threshold = -40.0;
        config.target_model = Some("GATE".to_string());
        let result = preflight_config(config);
        assert!(
            !result.messages.iter().any(|message| message.starts_with("Trigger: ")
                && message.contains("GATE")
                && message.contains("has no")),
            "GATE carries \"thr\": {:?}",
            result.messages
        );
    }

    /// The model slot travels on the catalogue row, so the editor can send the model it read for a
    /// strip with the plain keys as well: `gate_thr` and `eq_low_gain` carry one, `fader` and the
    /// on/off and model-selector keys carry none — those leaves exist whatever the model is, and a
    /// slot on them would make the editor offer a check the backend refuses to run.
    #[test]
    fn the_catalogue_dto_carries_the_model_slot_of_a_model_scoped_leaf() {
        let catalog = target_catalog(None);
        let channels = catalog
            .target_parameters_by_category
            .get("ch")
            .expect("the channel catalogue");
        let find = |key: &str| {
            channels
                .iter()
                .find(|parameter| parameter.key == key)
                .unwrap_or_else(|| panic!("{key} is offered for channels"))
        };

        assert_eq!(find("gate_thr").model_section, Some("gate"));
        assert_eq!(find("gate_thr").model_leaf, Some("thr"));
        assert_eq!(find("eq_low_gain").model_section, Some("eq"));
        assert_eq!(find("eq_low_gain").model_leaf, Some("lg"));
        assert_eq!(find("comp_thr").model_section, Some("dyn"));
        assert_eq!(find("comp_thr").model_leaf, Some("thr"));
        // The DEQ2 keys carry the appendix's own hyphenated names.
        assert_eq!(find("gate_1_thr").model_section, Some("gate"));
        assert_eq!(find("gate_1_thr").model_leaf, Some("1-thr"));

        for key in [
            "fader",
            "mute",
            "name",
            "gate_on",
            "comp_on",
            "eq_on",
            "gate_type",
            "comp_type",
        ] {
            let parameter = channels
                .iter()
                .find(|parameter| parameter.key == key)
                .unwrap_or_else(|| panic!("{key} is offered for channels"));
            assert_eq!(parameter.model_section, None, "{key} is not model-scoped");
            assert_eq!(parameter.model_leaf, None, "{key} is not model-scoped");
        }

        // The editor reads the DTO as JSON, so the names are the camelCase ones and an absent slot is
        // omitted rather than sent as null.
        let json = serde_json::to_value(find("gate_thr")).expect("the DTO serializes");
        assert_eq!(
            json.get("modelSection").and_then(|value| value.as_str()),
            Some("gate"),
            "{json}"
        );
        assert_eq!(
            json.get("modelLeaf").and_then(|value| value.as_str()),
            Some("thr"),
            "{json}"
        );
        let json = serde_json::to_value(find("fader")).expect("the DTO serializes");
        assert!(json.get("modelSection").is_none(), "{json}");
        assert!(json.get("modelLeaf").is_none(), "{json}");
    }

    /// The catalogue spelling of a model-scoped parameter gets the same "the model was not checked"
    /// note the `section:name` targets get: an older file, an import and a hand-edited show carry no
    /// model, and the write must not look verified when nothing decided it.
    #[test]
    fn a_catalogue_key_without_the_strips_model_is_accepted_with_a_note() {
        let mut config = model_parameter_step_config("ch", "comp_thr", None);
        // A value inside the range the catalogue documents, so the model is the only thing left that
        // could have been checked.
        config.action_steps[0].action_arg_kind = "float".to_string();
        config.action_steps[0].action_value = "-20".to_string();

        let result = preflight_config(config.clone());
        assert!(
            result.ok,
            "a macro saved before the model travelled must keep working: {:?}",
            result.messages
        );
        assert!(
            result.messages.iter().any(|message| message.starts_with("Step 1: ")
                && message.contains("was not checked")),
            "the note must say the model was not checked: {:?}",
            result.messages
        );
        assert!(configured_macro_from_config("macro-1".to_string(), config).is_ok());
    }

    /// The editor limits a text field to the console's documented length, but a hand-edited `.wcz`
    /// or an Android import never saw that field: a 40-character name was sent to the 16-character
    /// leaf `/ch/1/name` (Maillot 1986) and the console kept its old name in silence.
    #[test]
    fn a_step_value_longer_than_the_leaf_allows_is_refused() {
        let mut config = default_show_runner_config();
        let step = &mut config.action_steps[0];
        step.target_category = "ch".to_string();
        step.target_ids = "1".to_string();
        step.target_parameter = "name".to_string();
        step.send_id = Some(default_send_id());
        step.action_address = "/ch/1/name".to_string();
        step.action_arg_kind = "string".to_string();
        step.action_value = "B".repeat(40);

        let result = preflight_config(config.clone());
        assert!(!result.ok, "{:?}", result.messages);
        assert!(
            result
                .messages
                .iter()
                .any(|message| message.contains("at most 16 characters")),
            "the reason must name the limit: {:?}",
            result.messages
        );

        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a name longer than the leaf holds must not compile");
        assert!(error.contains("at most 16 characters"), "{error}");
    }

    /// A number outside the parameter's documented range is refused by the same shared value rule
    /// the trigger uses, in the compile path and not only in the window.
    #[test]
    fn a_step_value_outside_the_parameters_range_is_refused() {
        let mut config = default_show_runner_config();
        let step = &mut config.action_steps[0];
        step.target_category = "ch".to_string();
        step.target_ids = "1".to_string();
        step.target_parameter = "fader".to_string();
        step.send_id = Some(default_send_id());
        step.action_address = "/ch/1/fdr".to_string();
        step.action_arg_kind = "float".to_string();
        step.action_value = "-500".to_string();

        let problems = validate_macro_config(&normalize_show_runner_config(config.clone()));
        assert!(
            problems
                .iter()
                .any(|problem| problem.contains("has a minimum of -144 dB")),
            "the shared value rule must refuse it: {problems:?}"
        );
        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a fader below -144 dB must not compile");
        assert!(error.contains("minimum of -144"), "{error}");
    }

    /// The value rules belong to the parameter the selector names, and only to the address that
    /// selector resolves to. A step carrying a raw custom path must not be judged by a selector left
    /// over from another choice: the value goes to the address, not to the selector.
    #[test]
    fn a_raw_custom_address_is_not_judged_by_a_leftover_selector() {
        let mut config = default_show_runner_config();
        let step = &mut config.action_steps[0];
        step.target_category = "ch".to_string();
        step.target_ids = "1".to_string();
        step.target_parameter = "fader".to_string();
        step.action_address = "/custom/anything".to_string();
        step.action_arg_kind = "float".to_string();
        step.action_value = "-500".to_string();

        let problems = validate_macro_config(&normalize_show_runner_config(config));
        assert!(
            !problems.iter().any(|problem| problem.contains("minimum")),
            "the fader's range does not govern a custom address: {problems:?}"
        );

        // The same rule for a selector whose parameter has a closed list: `gate_type` is a list of
        // gate models, so a step left pointing at `/ch/2/name` while the selector still reads Gate
        // Model used to be refused with "Gate Model must be one of …" — a value the operator never
        // chose for the address that is actually written. A parameter with no options cannot see
        // this, which is why the range test above passes either way.
        let mut config = default_show_runner_config();
        let step = &mut config.action_steps[0];
        step.target_category = "ch".to_string();
        step.target_ids = "1".to_string();
        step.target_parameter = "gate_type".to_string();
        // The value is a name the closed list does not carry: the shape a raw custom write has.
        step.action_value = "VOX 1".to_string();
        step.action_arg_kind = "string".to_string();
        step.action_address = "/ch/2/name".to_string();

        let normalized = normalize_show_runner_config(config.clone());
        assert!(
            wing_core::targets::watch_rule("ch", "gate_type")
                .is_some_and(|rule| !rule.options.is_empty()),
            "the test needs a selector that really has a closed list"
        );
        let problems = validate_macro_config(&normalized);
        assert!(
            !problems.iter().any(|problem| problem.contains("must be one of")),
            "a leftover closed list does not govern a custom address: {problems:?}"
        );
        // …and the Shoot button applies the same rule, because it is the same function.
        assert!(
            !action_steps_problems(&sendable_action_steps(&config))
                .iter()
                .any(|problem| problem.contains("must be one of")),
            "the Shoot button must not refuse the step the macro accepts"
        );

        // The guard is about the *address*, not about the parameter: the same closed list still
        // governs the address it resolves to, so the check has not simply been switched off.
        let mut config = default_show_runner_config();
        let step = &mut config.action_steps[0];
        step.target_category = "ch".to_string();
        step.target_ids = "1".to_string();
        step.target_parameter = "gate_type".to_string();
        step.action_value = "VOX 1".to_string();
        step.action_arg_kind = "string".to_string();
        step.action_address = "/ch/1/gate/mdl".to_string();
        let problems = validate_macro_config(&normalize_show_runner_config(config));
        assert!(
            problems.iter().any(|problem| problem.contains("must be one of")),
            "the selector's own address is still judged by its list: {problems:?}"
        );
    }

    /// The Shoot button writes one step to a live console through the same dispatcher a macro run
    /// uses, so a step the macro itself could not contain must not go out — with the same reason.
    /// Only the steps are judged, and only the ones the dispatcher would send: an unfinished macro
    /// (no trigger, a half-configured second step) stays testable one step at a time, which is what
    /// the button is for.
    #[test]
    fn the_shoot_button_refuses_the_steps_the_macro_would_refuse() {
        let config_of = |parameter: &str, address: &str, arg_kind: &str, value: &str| {
            let mut config = default_show_runner_config();
            let step = &mut config.action_steps[0];
            step.target_category = "ch".to_string();
            step.target_ids = "1".to_string();
            step.target_parameter = parameter.to_string();
            step.send_id = Some(default_send_id());
            step.action_address = address.to_string();
            step.action_arg_kind = arg_kind.to_string();
            step.action_value = value.to_string();
            config
        };

        // A value outside the leaf's documented range.
        let problems =
            action_steps_problems(&sendable_action_steps(&config_of("fader", "/ch/1/fdr", "float", "-500")));
        assert!(
            problems
                .iter()
                .any(|problem| problem.contains("has a minimum of -144 dB")),
            "the Shoot button must not send what the macro refuses: {problems:?}"
        );

        // A name longer than the leaf holds, which the editor's own input also limits.
        let too_long = "B".repeat(40);
        let problems = action_steps_problems(&sendable_action_steps(&config_of(
            "name",
            "/ch/1/name",
            "string",
            &too_long,
        )));
        assert!(
            problems
                .iter()
                .any(|problem| problem.contains("at most 16 characters")),
            "{problems:?}"
        );

        // A name the model the editor read does not have.
        let problems = action_steps_problems(&sendable_action_steps(&model_parameter_step_config(
            "ch",
            "dyn:thr",
            Some("WARM"),
        )));
        assert!(
            problems.iter().any(|problem| problem.contains("WARM")),
            "the model rule applies to a shoot exactly as it does to a macro: {problems:?}"
        );

        // The step gate is not the macro validator: a trigger the window refuses does not stop a
        // complete step from being shot.
        let mut config = config_of("mute", "/ch/1/mute", "int", "1");
        config.trigger_category = "ch".to_string();
        config.trigger_parameter = "name".to_string();
        config.trigger_operator = ">".to_string();
        let normalized = normalize_show_runner_config(config);
        assert!(
            !validate_macro_config(&normalized).is_empty(),
            "the macro itself is refused: its trigger compares a text name with >"
        );
        assert!(
            action_steps_problems(&sendable_action_steps(&normalized)).is_empty(),
            "but the step is complete and valid, so the Shoot button still sends it"
        );

        // A second, half-configured step is neither sent nor judged: the dispatcher drops it, so it
        // cannot block the step the operator selected.
        let mut config = config_of("mute", "/ch/1/mute", "int", "1");
        let mut blank = default_action_step();
        blank.action_address = String::new();
        blank.target_parameter = "fader".to_string();
        blank.action_value = "-500".to_string();
        config.action_steps.push(blank);
        assert!(
            action_steps_problems(&sendable_action_steps(&config)).is_empty(),
            "a step with no address is dropped instead of written, so it must not block the shoot"
        );
    }

    /// A comparison the editor starts is seeded from the parameter itself, not from its value kind:
    /// the kind default is outside half the catalogue (Gate Range is 3…60, a ratio 1.1…100, and `1`
    /// is not a gate model), and a macro seeded with one was refused by its own validator.
    #[test]
    fn a_comparison_is_seeded_with_a_value_its_own_parameter_accepts() {
        for (category, parameter, operator) in [
            ("ch", "gate_range", ">"),
            ("ch", "comp_ratio", ">"),
            ("ch", "gate_type", "=="),
            ("ch", "mute", "=="),
        ] {
            let seed = wing_core::targets::default_comparison_value(category, parameter)
                .unwrap_or_else(|| panic!("{parameter} must have a seed"));
            assert!(
                wing_core::targets::value_problem(category, parameter, &seed).is_none(),
                "{parameter} must accept the value it seeds ({seed})"
            );

            let mut config = default_show_runner_config();
            config.trigger_category = category.to_string();
            config.trigger_ids = "1".to_string();
            config.trigger_parameter = parameter.to_string();
            config.trigger_operator = operator.to_string();
            config.trigger_value = None;
            // A numeric comparison travels in `trigger_threshold` and every other kind in
            // `trigger_value`; the editor seeds whichever field the kind uses, and this side has to
            // accept both.
            if let Ok(number) = seed.parse::<f32>() {
                config.trigger_threshold = number;
            }
            assert_eq!(
                trigger_comparison_value(&config),
                seed,
                "{parameter}: the trigger compares the seeded value"
            );
            let result = preflight_config(config);
            assert!(result.ok, "{parameter}: {:?}", result.messages);
        }

        // The defaults the seed replaces, and why it exists: both are refused by their own parameter.
        assert!(wing_core::targets::value_problem("ch", "gate_range", "-18").is_some());
        assert!(wing_core::targets::value_problem("ch", "gate_type", "1").is_some());
    }

    /// A free-text comparison has no seed, and the on/off default is not one: a name trigger with no
    /// value typed used to become `name == "1"`, which preflight accepted, which armed, and which the
    /// console could never satisfy — a name is never `"1"`. The empty value is handed to the shared
    /// validator instead, so the operator reads its own "needs a value" reason; the kinds that do
    /// have a seed keep it.
    #[test]
    fn a_text_trigger_with_no_value_is_refused_instead_of_comparing_with_one() {
        let mut config = default_show_runner_config();
        config.trigger_category = "ch".to_string();
        config.trigger_ids = "1".to_string();
        config.trigger_parameter = "name".to_string();
        config.trigger_operator = "==".to_string();
        config.trigger_value = None;

        assert_eq!(
            trigger_comparison_value(&config),
            "",
            "a name has no seed: nothing may be invented for it"
        );
        let result = preflight_config(config.clone());
        assert!(
            !result.ok,
            "a name compared with an empty string can never be true: {:?}",
            result.messages
        );
        assert!(
            result.messages.iter().any(|message| message.starts_with("Trigger: ")
                && message.contains("needs a value")),
            "the validator's own reason must be the one shown: {:?}",
            result.messages
        );
        let error = configured_macro_from_config("macro-1".to_string(), config)
            .err()
            .expect("a name trigger with no value must not compile");
        assert!(error.contains("needs a value"), "{error}");

        // What the operator typed is still what is compared.
        let mut typed = default_show_runner_config();
        typed.trigger_category = "ch".to_string();
        typed.trigger_ids = "1".to_string();
        typed.trigger_parameter = "name".to_string();
        typed.trigger_operator = "==".to_string();
        typed.trigger_value = Some("VOX 1".to_string());
        assert_eq!(trigger_comparison_value(&typed), "VOX 1");

        // The kinds that do have a seed keep it: a closed list starts at its first documented entry
        // and an on/off parameter at 1.
        let seed_for = |parameter: &str| {
            let mut config = default_show_runner_config();
            config.trigger_category = "ch".to_string();
            config.trigger_ids = "1".to_string();
            config.trigger_parameter = parameter.to_string();
            config.trigger_value = None;
            trigger_comparison_value(&config)
        };
        assert_eq!(
            seed_for("gate_type"),
            wing_core::targets::default_comparison_value("ch", "gate_type")
                .expect("a closed list has a first entry"),
            "a closed list still starts at its first documented entry"
        );
        assert_eq!(seed_for("mute"), "1", "an on/off trigger still seeds 1");
    }

    /// The output source group is the console's own list (Maillot 1844-1846). The editor offered
    /// `SEND` while the backend refused it, and `USR`, `SEND` and `MON` could not be selected at
    /// all; every option the editor now offers has to validate.
    #[test]
    fn the_output_group_list_matches_the_document() {
        let catalog = target_catalog(None);
        let group = catalog
            .target_parameters_by_category
            .get("output_usb")
            .expect("output usb target parameters")
            .iter()
            .find(|parameter| parameter.key == "output_group")
            .expect("the output source group is offered");

        for option in &group.options {
            let mut config = default_show_runner_config();
            config.action_steps[0].target_category = "output_usb".to_string();
            config.action_steps[0].target_ids = "1".to_string();
            config.action_steps[0].target_parameter = "output_group".to_string();
            config.action_steps[0].action_value = option.value.to_string();
            config.action_steps[0].action_arg_kind = "string".to_string();
            let problems = validate_macro_config(&normalize_show_runner_config(config));
            assert!(
                !problems.iter().any(|problem| problem.contains("Output Source Group")),
                "'{}' is offered but refused: {problems:?}",
                option.value
            );
        }

        for documented in ["SEND", "MON", "USR"] {
            assert!(
                group
                    .options
                    .iter()
                    .any(|option| option.value == documented),
                "{documented} is documented at 1844-1846"
            );
        }
        // The codes the previous list invented are not the console's and must stay refused.
        for invented in ["INP", "USBREC", "SIG"] {
            assert!(
                !group.options.iter().any(|option| option.value == invented),
                "{invented} was never a documented group"
            );
        }
    }

