    #[test]
    fn condition_operators_follow_value_semantics() {
        // Continuous Maillot meter levels accept crossing comparators only.
        assert!(condition_operator_allowed("db_meter", ">"));
        assert!(condition_operator_allowed("db_meter", "<"));
        assert!(!condition_operator_allowed("db_meter", "=="));
        assert!(!condition_operator_allowed("meter_state", "!="));

        // V2 gate/dyn state slots and OSC toggles accept equality only.
        assert!(condition_operator_allowed("toggle", "=="));
        assert!(condition_operator_allowed("toggle", "!="));
        assert!(!condition_operator_allowed("toggle", ">"));

        // Free text and route codes also compare by equality.
        assert!(condition_operator_allowed("text", "=="));
        assert!(!condition_operator_allowed("route_group", "<"));

        // OSC numeric state accepts order and equality.
        assert!(condition_operator_allowed("db", ">"));
        assert!(condition_operator_allowed("hz", "=="));
        assert!(condition_operator_allowed("integer", "!="));

        // Operators are normalized before the check, so `>=` behaves as `>`.
        assert!(condition_operator_allowed("db_meter", ">="));
    }

    #[test]
    fn condition_values_are_normalized_per_value_kind() {
        // **The clamp is deliberate, and this is where it is pinned.** An out-of-range condition becomes a
        // *different* condition — `meter < -999` ("never true") is rewritten to `< -120`, which a silent
        // channel satisfies (Maillot's own example reports 0x8000 = -128) — while an out-of-range action
        // value is refused, and the audit called that divergence out (2026-10-02, M3).
        //
        // Refusing here was considered and rejected on purpose: this normalization runs on the **compile**
        // path, so a refusal would stop a macro that runs today, on a path that also runs when a saved show
        // is armed — the wrong place to discover a value the operator typed months ago. The UI's own
        // controls are bounded to the published range, so a typed value outside it is already unusual; if
        // the operator is ever to be told, it belongs in the preflight notes, which is what
        // docs/DEFINITIVE_VERSION_PLAN_2026-10-02.md records as the remaining half of this finding.
        let toggle = parameter_value_metadata("mute", "int");
        assert_eq!(normalize_condition_value(&toggle, " ON ").unwrap(), "1");
        assert_eq!(normalize_condition_value(&toggle, "off").unwrap(), "0");
        assert!(normalize_condition_value(&toggle, "maybe").is_err());

        let meter = parameter_value_metadata("meter", "float");
        assert_eq!(
            normalize_condition_value(&meter, " -18.5 ").unwrap(),
            "-18.5"
        );
        assert_eq!(normalize_condition_value(&meter, "-999").unwrap(), "-120");
        assert_eq!(normalize_condition_value(&meter, "999").unwrap(), "24");
        assert!(normalize_condition_value(&meter, "loud").is_err());

        let ratio = parameter_value_metadata("comp_ratio", "float");
        assert_eq!(normalize_condition_value(&ratio, "-5").unwrap(), "1");

        let integer = parameter_value_metadata("comp_knee", "int");
        assert_eq!(normalize_condition_value(&integer, "2.6").unwrap(), "3");

        let group = parameter_value_metadata("output_group", "string");
        assert_eq!(normalize_condition_value(&group, " lcl ").unwrap(), "LCL");
        assert!(normalize_condition_value(&group, "aes50a").is_err());

        // Free text keeps whatever the operator typed, including an empty value.
        let name = parameter_value_metadata("name", "string");
        assert_eq!(normalize_condition_value(&name, "  ").unwrap(), "");

        // Every kind except text still requires a value.
        assert!(normalize_condition_value(&meter, "   ").is_err());
    }

