    #[test]
    fn refresh_slot_never_moves_the_limiter_backwards() {
        // The state refresh is allowed to send while a ramp step has a slot reserved, so staleness
        // stays bounded, but it must not pull the limiter back: that would let a later reservation
        // overlap an already queued send.
        let base = Instant::now();

        // A reserved slot stays reserved and keeps its spacing.
        let mut reserved = base + Duration::from_millis(50);
        reserve_refresh_slot(&mut reserved, base);
        assert_eq!(reserved, base + Duration::from_millis(50));

        // An idle limiter takes the slot normally.
        let mut idle = base;
        reserve_refresh_slot(&mut idle, base);
        assert_eq!(idle, base + OSC_SEND_INTERVAL);
    }

    #[test]
    fn saturated_osc_queue_is_distinguishable_from_an_operator_stop() {
        // The stream thread aborts only on a real stop. A saturated queue must be
        // reported as such so a burst of macro traffic degrades instead of killing
        // the meter stream mid-show.
        let now = Instant::now();
        let mut next = now + OSC_MAX_QUEUE_DELAY + Duration::from_millis(1);
        assert!(matches!(
            reserve_osc_send(&mut next, now),
            Err(OscSendError::QueueFull)
        ));

        let mut healthy = now;
        assert!(matches!(reserve_osc_send(&mut healthy, now), Ok(_)));
        assert_ne!(
            OscSendError::QueueFull.to_string(),
            OscSendError::Cancelled.to_string()
        );
        assert_eq!(String::from(OscSendError::Cancelled), "OSC send cancelled");
    }

    #[test]
    fn deliberate_stops_are_aborted_not_failed() {
        // Panic stop sets the stream flag and the per-action flag; a network
        // timeout sets the stream flag. Both mean "stopped on purpose", so the
        // outcome must be `aborted`, never `failed`.
        let action_stop = Arc::new(AtomicBool::new(false));
        let stream_stop = Arc::new(AtomicBool::new(false));
        assert!(!action_outcome_was_deliberate(&action_stop, &stream_stop));

        action_stop.store(true, Ordering::Relaxed);
        assert!(action_outcome_was_deliberate(&action_stop, &stream_stop));

        action_stop.store(false, Ordering::Relaxed);
        stream_stop.store(true, Ordering::Relaxed);
        assert!(action_outcome_was_deliberate(&action_stop, &stream_stop));
    }

    #[test]
    fn get_reply_and_event_share_one_value_selection_rule() {
        // `,sff` reply: ascii, raw, value -> the value is last.
        let reply = vec![
            OscStateValue::String("-21.8".to_string()),
            OscStateValue::Float(0.3531),
            OscStateValue::Float(-21.752),
        ];
        assert_eq!(
            state_value_from_reply(reply),
            Some(OscStateValue::Float(-21.752))
        );
        // Event: single tag data -> used as-is.
        assert_eq!(
            state_value_from_reply(vec![OscStateValue::Int(1)]),
            Some(OscStateValue::Int(1))
        );
        // Non-leaf node listing: child keys, not a state value.
        assert_eq!(
            state_value_from_reply(vec![
                OscStateValue::String("$mode".to_string()),
                OscStateValue::String("srcauto".to_string()),
            ]),
            None
        );
    }

    #[test]
    fn toggle_mode_survives_normalization_and_the_runtime_conversion() {
        // The executor is proven on hardware, so a toggle that does not run means the
        // mode was lost on the way there. This walks the whole chain.
        let mut config = default_show_runner_config();
        config.name = "toggle alt source".to_string();
        // Only enabled macros are armed into the runtime, like an operator would have.
        config.enabled = true;
        config.action_steps[0].action_mode = "toggle".to_string();
        config.action_steps[0].target_category = "ch".to_string();
        config.action_steps[0].target_ids = "36".to_string();
        config.action_steps[0].target_parameter = "alt_source".to_string();
        config.action_steps[0].action_address = "/ch/36/in/set/altsrc".to_string();
        config.action_steps[0].action_arg_kind = "int".to_string();
        config.action_steps[0].action_value = "1".to_string();

        let normalized = normalize_show_runner_config(config);
        assert_eq!(
            normalized.action_steps[0].action_mode, "toggle",
            "normalize_show_runner_config must not rewrite the toggle mode"
        );

        let library = MacroLibraryDto {
            schema_version: 1,
            selected_index: 0,
            macros: vec![normalized],
        };
        let macros = configured_macros_from_library(Some(library), default_show_runner_config())
            .expect("runtime conversion")
            .macros;
        let step = &macros[0].action.steps[0];
        assert_eq!(
            step.mode, "toggle",
            "the runtime step must keep the toggle mode it was saved with"
        );
        assert_eq!(step.address, "/ch/36/in/set/altsrc");
    }

    #[test]
    fn test_action_shoot_runs_the_step_through_the_dispatcher() {
        // "Test Action (Shoot)" must reach `execute_configured_show_action`. It used to
        // call `send_osc_message` with the step's raw address/value, which dropped the
        // toggle mode: a toggle step stores no value by design, so the console received a
        // fixed value and the parameter never alternated.
        let mut config = default_show_runner_config();
        config.action_steps[0].action_mode = "toggle".to_string();
        config.action_steps[0].target_category = "ch".to_string();
        config.action_steps[0].target_ids = "36".to_string();
        config.action_steps[0].target_parameter = "alt_source".to_string();
        config.action_steps[0].action_address = "/ch/36/in/set/altsrc".to_string();
        config.action_steps[0].action_value = String::new();

        let action = configured_osc_action_for_config(&config)
            .expect("a one-step config must convert into a runnable action");
        assert_eq!(action.steps.len(), 1, "the shoot test must run exactly the sent step");
        assert_eq!(
            action.steps[0].mode, "toggle",
            "the shoot path must keep the toggle mode instead of sending a raw value"
        );
        assert_eq!(action.steps[0].address, "/ch/36/in/set/altsrc");
    }

