    #[test]
    // Needs a real console: without `LIVE_WING_OSC_TEST` it returns early, and a test that passes by returning
    // early is counted as coverage while asserting nothing. Ignored so `cargo test` says so out loud
    // (audit 2026-10-02, S4).
    #[ignore = "needs a real WING console: set LIVE_WING_OSC_TEST=1 and run with --ignored"]
    fn live_wing_osc_state_refresh_reads_and_caches_the_real_value() {
        if std::env::var("LIVE_WING_OSC_TEST").is_err() {
            return;
        }
        let wing_ip = Ipv4Addr::new(192, 168, 1, 10);
        let route = probe_wing_route(wing_ip, None, false).expect("identity route");
        let udp = route.hub;
        let target = console_osc_target(&wing_ip);

        assert!(
            try_send_osc_read(&udp, "/ch/1/fdr", &target),
            "the refresh read was not sent"
        );

        let mut cache = OscStateCache::new();
        let mut buffer = [0_u8; 8192];
        let deadline = Instant::now() + Duration::from_secs(2);
        while Instant::now() < deadline {
            if let Ok((len, source)) = udp.recv_once(&mut buffer, Duration::from_millis(250)) {
                if source.ip() != IpAddr::V4(wing_ip) {
                    continue;
                }
                if let Some((address, values)) = decode_osc_state_packet(&buffer[..len]) {
                    update_osc_state_cache(&mut cache, address, values);
                    if cache.contains_key("/ch/1/fdr") {
                        break;
                    }
                }
            }
        }

        match cache.get("/ch/1/fdr").map(|(value, _)| value.clone()) {
            Some(OscStateValue::Float(value)) => {
                println!("refresh read cached /ch/1/fdr = {value} dB");
            }
            other => panic!("expected a real float value from the refresh, got {other:?}"),
        }
    }

    #[test]
    fn json_loaders_fall_back_to_the_recovery_copy() {
        let unique = SAVE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!(
            "wing-desktop-recovery-{}-{unique}",
            std::process::id()
        ));
        let path = dir.join("show_runner_config.json");
        write_json_with_recovery(&path, "{\"version\":1}").expect("first write");
        write_json_with_recovery(&path, "{\"version\":2}").expect("second write");

        // The main file holds v2 and the recovery copy holds v1.
        fs::write(&path, "{ this is not json").expect("corrupt the main file");
        let (value, backup) =
            read_json_with_recovery::<serde_json::Value>(&path).expect("recovery must succeed");
        assert_eq!(value["version"], 1, "the recovery copy is the older, good one");
        assert!(backup.is_some(), "the caller must be told a recovery copy was used");

        // A good main file is preferred and reports no recovery.
        fs::write(&path, "{\"version\":3}").expect("rewrite");
        let (value, backup) =
            read_json_with_recovery::<serde_json::Value>(&path).expect("primary read");
        assert_eq!(value["version"], 3);
        assert!(backup.is_none());

        // A broken file with no recovery copy must fail loudly, not silently.
        let lonely = dir.join("macros.json");
        fs::write(&lonely, "nope").expect("write");
        assert!(read_json_with_recovery::<serde_json::Value>(&lonely).is_err());

        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn verification_targets_are_deduplicated_and_meter_addresses_are_skipped() {
        let library = MacroLibraryDto {
            schema_version: 1,
            selected_index: 0,
            macros: vec![
                {
                    let mut config = default_show_runner_config();
                    config.name = "One".to_string();
                    config.trigger_category = "ch".to_string();
                    config.trigger_parameter = "mute".to_string();
                    config.trigger_ids = "1".to_string();
                    config.action_steps[0].action_address = "/ch/1/mute".to_string();
                    config.action_steps[0].action_mode = "set".to_string();
                    config.conditions = vec![ShowConditionDto {
                        label: "gate".to_string(),
                        target_category: "ch".to_string(),
                        target_ids: "2".to_string(),
                        target_parameter: "mute".to_string(),
                        send_id: None,
                        target_model: None,
                        operator: "==".to_string(),
                        value: "1".to_string(),
                        enabled: true,
                    }];
                    config
                },
                {
                    let mut config = default_show_runner_config();
                    config.name = "Two".to_string();
                    config.trigger_category = "ch".to_string();
                    config.trigger_parameter = "meter".to_string();
                    config.trigger_ids = "1".to_string();
                    config.action_steps[0].action_address = "/ch/1/mute".to_string();
                    config.action_steps[0].action_mode = "toggle".to_string();
                    config
                },
            ],
        };

        let targets = verification_targets(&library);
        let addresses = targets.iter().map(|(address, _)| address.as_str()).collect::<Vec<_>>();
        // `/ch/1/mute` appears as an action in both macros and as a trigger in the
        // first, so it must be listed once with every source label.
        assert_eq!(addresses.iter().filter(|address| **address == "/ch/1/mute").count(), 1);
        let mute = targets.iter().find(|(address, _)| address == "/ch/1/mute").expect("mute");
        assert_eq!(mute.1.len(), 3, "expected three labels, got {:?}", mute.1);
        // The IF condition resolves to its own address and is included.
        assert!(addresses.contains(&"/ch/2/mute"), "{addresses:?}");
        // A meter trigger is binary, not an OSC leaf.
        assert!(!addresses.contains(&"/meters/ch/1"), "{addresses:?}");
    }

